L[#L+1]={cen="Young Lovers",give={id=251,k="npc",m=12,n="Maybell Maclure",x=0.431,y=0.896},id=106,lvl=6,mn=5,money=0,pl=8,rc=589,rep={Stormwind=28},t="Junge Liebende",turn={id=252,k="npc",m=12,n="Tommy Joe Stonefield",x=0.299,y=0.86},tx={d="Oh, I'm cursed! My heart belongs to Tommy Joe Stonefield, but our families are bitter enemies. So I can't see him, even though my eyes ache to gaze upon that handsome face!{br}Please, take this letter and give it to Tommy Joe. He's usually at the river to the west of the Stonefield Farm, which is due west of here.",o="Give Maybell's Love Letter to Tommy Joe Stonefield.",p="You have what?? Maybell is the light of my dull life. Hurry, let me see her letter!",r="Ah! I can't stand us being apart. I have to see her!!"},upd=1792881447,xp=202,y="q",zone=12}
L[#L+1]={cen="Note to William",give={id=248,k="npc",m=12,n="Gramma Stonefield",x=0.349,y=0.839},id=107,lvl=6,mn=5,money=0,pl=8,pre={111},rc=589,rep={Stormwind=28},t="Nachricht an William",turn={id=253,k="npc",m=12,n="William Pestle",x=0.433,y=0.658},tx={d="I bet William Pestle has a potion to unite our two young lovers!{br}Here, take this note to William. He's staying at the Lion's Pride Inn in Goldshire.",o="Take Gramma Stonefield's Note to William Pestle.",p="You have a note from \"Gramma\" Stonefield, eh? I haven't seen Mildred in years! I wonder what she has to say...",r="My heart goes out to those two poor souls, Maybell and Tommy Joe. I remember being young and in love, once.{br}There must be something I can do to help them! Let me think..."},upd=1792881616,xp=203,y="q",zone=12}
L[#L+1]={cen="Elmore's Task",give={id=514,k="npc",m=12,n="Smith Argus",x=0.417,y=0.656},id=1097,lvl=15,mn=9,money=0,pl=9,rc=589,t="Elmores Aufgabe",turn={id=1416,k="npc",m=1519,n="Grimand Elmore",x=0.597,y=0.339},tx={d="There's a dwarven weaponsmith in Stormwind, Grimand Elmore, who sent word that he needs help with a delivery. I believe he wants a package sent to his homeland in the north.{br}You have a sturdy pair on you! So if you're interested in some legwork then speak with Grimand. We could use you down here, but we must also keep our ties strong with the dwarves.{br}You can find Grimand Elmore at the weapon shop in the Dwarven District of Stormwind, in the northeast section of town.",o="Speak with Grimand Elmore.",r="You're here to help with my delivery? Very good!"},upd=1792935236,xp=158,y="q",zone=12}
L[#L+1]={cen="Speak with Gramma",give={id=252,k="npc",m=12,n="Tommy Joe Stonefield",x=0.299,y=0.86},id=111,lvl=6,mn=5,money=0,pl=8,pre={106},rc=589,rep={Stormwind=27},t="Gespräch mit Oma",turn={id=248,k="npc",m=12,n="Gramma Stonefield",x=0.349,y=0.839},tx={d="Please, $N, talk with my Gramma. If anyone can find a way to bring me together with Maybell, she can.{br}She's inside our house east of here.",o="Speak with Gramma Stonefield.",r="While our families are feuding, Tommy Joe and Maybell don't have much of a future, but... maybe we can get them together for just a little while.{br}Hm, what can we do..."},upd=1792881497,xp=202,y="q",zone=12}
L[#L+1]={cen="Collecting Kelp",give={id=253,k="npc",m=12,n="William Pestle",x=0.433,y=0.658},id=112,lvl=7,mn=5,money=0,obj={{name="Crystal Kelp Frond",req=4,txt="Crystal Kelp Frond: 0/4",ty="item"}},pl=9,pre={107},rc=589,t="Die Suche nach dem Tang",turn={id=253,k="npc",m=12,n="William Pestle",x=0.433,y=0.657},tx={d="I can make an invisibility liquor for Maybell, so she can slip away from the Maclure Vineyards and go to Tommy Joe. But to make the Liquor, I need some crystal kelp.{br}Although the kelp usually grows in the ocean... sometimes murlocs collect it. See if the murlocs near Crystal Lake have any. Crystal Lake is just east of Goldshire.",o="Bring 4 Crystal Kelp Fronds to William Pestle in Goldshire."},upd=1792881859,y="q",zone=12}
L[#L+1]={cen="Frostmaw",give={id=3441,k="npc",m=215,n="Melor Stonehoof",x=0.423,y=0.333},id=1136,lvl=37,mn=26,obj={{name="Frostmaw's Mane",req=1,txt="Frostmaw's Mane: 1/1",ty="item"}},pre={1131},rc=434,t="Frostrachen",turn={id=3441,k="npc",m=215,n="Melor Stonehoof",x=0.423,y=0.333},upd=1793307054,y="q"}
L[#L+1]={cen="Blueleaf Tubers",give={id=3446,k="npc",m=17,n="Mebok Mizzyrix",x=0.624,y=0.376},id=1221,lvl=26,mn=20,obj={{name="Blueleaf Tuber",req=6,txt="Blueleaf Tuber: 0/6",ty="item"},{name="Crate With Holes",req=1,txt="Crate With Holes: 1/1",ty="item"},{name="Snufflenose Owner's Manual",req=1,txt="Snufflenose Owner's Manual: 1/1",ty="item"},{name="Snufflenose Command Stick",req=1,txt="Snufflenose Command Stick: 1/1",ty="item"}},t="Blaulaubknollen",turn={id=3446,k="npc",m=17,n="Mebok Mizzyrix",x=0.624,y=0.376},upd=1793307054,y="q"}
L[#L+1]={cen="Wharfmaster Dizzywig",give={id=3390,k="npc",m=17,n="Apothecary Helbrim",x=0.514,y=0.302},id=1492,lvl=11,mn=9,rc=434,t="Werftmeister Dizzywig",turn={id=3453,k="npc",m=17,n="Wharfmaster Dizzywig",x=0.634,y=0.385},upd=1793307054,y="q"}
L[#L+1]={cen="Investigate Echo Ridge",give={id=197,k="npc",m=12,n="Marshal McBride",x=0.489,y=0.416},id=15,lvl=3,mn=1,money=40,obj={{ids={[257]=5},name="Kobold Worker",req=10,txt="Kobold Worker slain: 0/10",ty="monster"}},pl=4,pre={7},rc=589,rep={Stormwind=110},t="Überprüfung der Echokammmine",ta={max=4730,min=2240,n=2,sum=6970},tm={max=2770,min=1460,n=2,sum=4230},tr={max=2770,min=1460,n=2,sum=4230},turn={id=197,k="npc",m=12,n="Marshal McBride",x=0.489,y=0.417},tx={d="$N, my scouts tell me that the kobold infestation is larger than we had thought. A group of kobold workers has camped near the Echo Ridge Mine to the north.{br}Go to the mine and remove them. We know there are at least 10. Kill them, see if there are more, then report back to me.",o="Kill 10 Kobold Workers, then report back to Marshal McBride.",r="I don't like hearing of all these kobolds in our mine. No good can come of this. Here, take this as payment, and when you're ready, speak to me again. I would like you to go back to the mines one more time..."},upd=1792845248,xp=375,y="q",zone=12}
L[#L+1]={cen="Poor Old Blanchy",fixed={{c=1,id=2165},{c=1,id=1537}},give={id=238,k="npc",m=40,n="Verna Furlbrow",x=0.6,y=0.195},id=151,lvl=14,mn=9,money=0,obj={{name="Handful of Oats",req=8,txt="Handful of Oats: 0/8",ty="item"}},pl=10,rc=589,t="Die arme Graumähne",turn={id=238,k="npc",m=40,n="Verna Furlbrow",x=0.599,y=0.194},tx={d="Poor Old Blanchy! Such a tired beast after all the work we put her through. I fed her before we left the farm, but we weren't expecting the wagon to break on us. If you could bring her a few handfuls of oats from the fields, I'd be grateful.{br}I bet you could find some around all of the farms in Westfall, if you can steer clear of those horrific machines that have taken over. There are several farms southwest of here.",o="Verna Furlbrow in Westfall wants you to bring her 8 Handfuls of Oats."},upd=1792928948,y="q",zone=40}
L[#L+1]={cen="Call of Earth",cl=64,give={id=5887,k="npc",m=14,n="Canaga Earthcaller",x=0.425,y=0.691},id=1516,lvl=4,mn=4,money=0,obj={{item=6640,name="Felstalker Hoof",req=2,txt="Felstalker Hoof: 0/2",ty="item"}},pl=4,qi={[6640]={u3102=3}},rc=130,t="Ruf der Erde",ta={max=2762,min=2762,n=1,sum=2762},tm={max=235,min=235,n=1,sum=235},tr={max=470,min=470,n=1,sum=470},turn={id=5887,k="npc",m=14,n="Canaga Earthcaller",x=0.424,y=0.691},tx={d="The time is now, young shaman. You've grown strong and your spirit endures like the earth. Following the shaman's path shows you have wisdom before even proving yourself.{br}The element of earth will guide your destiny, becoming part of you if you are ready. But you must stand before the earth itself. If you are ready, then you will see things only shaman know of.{br}Seek out the Felstalkers to the north, and take from them two of their hooves. Return to me then, and we shall speak more of your future.",o="Bring 2 Felstalker Hooves to Canaga Earthcaller in the Valley of Trials.",p="Patience is earth's greatest virtue. The earth witnesses the cycle of all things: the mountains becoming deserts; rivers becoming canyons. The earth is the most stubborn and wise of all the elements and it does not tolerate impatience.{br}The earth beckons you now because a time of conflict draws near. When you return to me successful, then you shall be that much closer to being made whole.{br}Oth",r="Excellent. Your success shows that you are prepared.{br}Of all the elements, earth represents the foundation of all things. It is your strength, your stamina, and your patience. Earth will protect you, but only if shown the proper respect. Like the other elements, even earth can be fickle. Earth is the basis for life, and by observing its laws, you will gain greater wisdom. Never forget the secrets earth shares with you.{br}I shall make a sapta for you now, and by accepting it, you will realize your path."},upd=1793359013,xp=337,y="q",zone=14}
L[#L+1]={cen="Call of Earth",cl=64,give={id=5887,k="npc",m=14,n="Canaga Earthcaller",x=0.424,y=0.691},id=1517,lvl=4,mn=4,money=0,pl=6,pre={1516},rc=434,t="Ruf der Erde",turn={id=5891,k="npc",m=14,n="Minor Manifestation of Earth",x=0.441,y=0.761},tx={d="A sapta is a drink created to bind our spirits to the elements. Fused with magic, the potion will allow the strong willed to see the elements as no one else can. Your spirit will be connected to the element the sapta was created for, and only a select few shaman know the recipe.{br}The sapta is always drunk in a holy place, and never anywhere else--remember that.{br}Seek out Spirit Rock southwest of here--it is found at the end of the Hidden Path. Drink your sapta there, and... well, you shall see.",o="Find Spirit Rock and drink the Earth Sapta."},upd=1793359238,xp=338,y="q",zone=14}
L[#L+1]={cen="Call of Earth",cl=64,fixed={{c=1,id=5175}},give={id=5891,k="npc",m=14,n="Minor Manifestation of Earth",x=0.441,y=0.761},id=1518,lvl=4,mn=4,money=0,pl=6,pre={1517},rc=434,t="Ruf der Erde",turn={id=5887,k="npc",m=14,n="Canaga Earthcaller",x=0.424,y=0.691},tx={d="Take this rough quartz from me and bring it to Canaga Earthcaller as proof of our meeting. He will craft a totem for you, and this pebble will be the heart of it. As small as it may seem, you will come to find that size does not matter, and that even the smallest of things can outlast many others.{br}Be patient, $N. Remain strong. And seek wisdom. This is what earth asks of you. In the end, you shall become one with the earth--respect it as it shall respect you.",o="Bring the Rough Quartz to Canaga Earthcaller in the Valley of Trials."},upd=1793359287,xp=557,y="q",zone=14}
L[#L+1]={cen="Call of Fire",cl=64,give={id=5907,k="npc",m=17,n="Kranal Fiss",x=0.56,y=0.2},id=1524,lvl=11,mn=10,money=0,pl=12,pre={2983},rc=434,t="Ruf des Feuers",turn={id=5900,k="npc",m=14,n="Telf Joolam",x=0.386,y=0.589},tx={d="You are powerful enough to wield the totem of fire, but that does not mean you are ready.{br}Along the Southfury River in Durotar, before the Great Sea, lies a hidden trail to one of the highest peaks in the land. Find your way to the top and you shall find one of our holy shrines watched over by Telf Joolam--the Shrine of the Dormant Flame.{br}Take this torch to him--it marks that you attempt to tame fire. Return it to me aflame by the brazier at the shrine and I will see you are given the totem of fire.",o="Bring the Torch of the Dormant Flame to Telf Joolam in Durotar."},upd=1793053740,xp=990,y="q",zone=17}
L[#L+1]={cen="Call of Fire",cl=64,give={id=5900,k="npc",m=14,n="Telf Joolam",x=0.386,y=0.59},id=1525,lvl=12,mn=10,obj={{name="Fire Tar",req=1,txt="Fire Tar: 0/1",ty="item"},{name="Reagent Pouch",req=1,txt="Reagent Pouch: 0/1",ty="item"}},pre={1524},rc=434,t="Ruf des Feuers",turn={id=5900,k="npc",m=14,n="Telf Joolam",x=0.386,y=0.59},upd=1793307054,y="q"}
L[#L+1]={cen="Brotherhood of Thieves",choice={{c=1,id=2224},{c=1,id=5580},{c=1,id=1161},{c=1,id=5579},{c=1,id=1159}},give={id=823,k="npc",m=12,n="Deputy Willem",x=0.481,y=0.429},id=18,lvl=4,mn=2,money=0,obj={{item=752,name="Red Burlap Bandana",req=12,txt="Red Burlap Bandana: 0/12",ty="item"}},pl=3,pre={783},qi={[752]={u38=13}},rc=589,rep={Stormwind=110},t="Bruderschaft der Diebe",ta={max=1970,min=1970,n=1,sum=1970},tm={max=1530,min=1530,n=1,sum=1530},tr={max=1530,min=1530,n=1,sum=1530},turn={id=823,k="npc",m=12,n="Deputy Willem",x=0.482,y=0.43},tx={d="Recently, a new group of thieves has been hanging around Northshire. They call themselves the Defias Brotherhood, and have been seen across the river to the east.{br}I don't know what they're up to, but I'm sure it's not good! Bring me the bandanas they wear, and I'll reward you with a weapon.",o="Bring 12 Red Burlap Bandanas to Deputy Willem outside the Northshire Abbey.",p="Have you gathered those bandanas for me yet?",r="Back with some bandanas, I see. The Stormwind Army appreciates your help."},upd=1792845937,xp=533,y="q",zone=12}
L[#L+1]={cen="Skirmish at Echo Ridge",choice={{c=1,id=2186},{c=1,id=2691},{c=1,id=11192}},give={id=197,k="npc",m=12,n="Marshal McBride",x=0.489,y=0.417},id=21,lvl=5,mn=1,money=0,obj={{ids={[80]=5},name="Kobold Laborer",req=12,txt="Kobold Laborer slain: 0/12",ty="monster"}},pl=4,pre={15},rc=589,rep={Stormwind=110},t="Scharmützel in der Echokammmine",ta={max=5790,min=3680,n=2,sum=9470},tm={max=2400,min=2300,n=2,sum=4700},tr={max=2400,min=2300,n=2,sum=4700},turn={id=197,k="npc",m=12,n="Marshal McBride",x=0.489,y=0.416},tx={d="Your previous investigations are proof that the Echo Ridge Mine needs purging. Return to the mine and help clear it of kobolds.{br}Waste no time, $N. The longer the kobolds are left unmolested in the mine, the deeper a foothold they gain in Northshire.",o="Kill 12 Kobold Laborers, then return to Marshal McBride at Northshire Abbey.",r="Once again, you have earned my respect, and the gratitude of the Stormwind Army. There may yet be kobolds in the mine, but I will marshal others against them. We have further tasks for you."},upd=1792845672,xp=675,y="q",zone=12}
L[#L+1]={cen="Rest and Relaxation",choice={{c=5,id=4656},{c=5,id=159}},give={id=6774,k="npc",m=12,n="Falkhaan Isenstrider",x=0.456,y=0.478},id=2158,lvl=5,mn=1,money=0,pl=6,rc=589,rep={Stormwind=28},t="Ruhe und Entspannung",turn={id=295,k="npc",m=12,n="Innkeeper Farley",x=0.436,y=0.66},tx={d="Every adventurer should rest when exhaustion sets in - and there is no finer place to get rest and relaxation than at the Lion's Pride Inn!{br}My best friend, Innkeeper Farley, runs the Lion's Pride. If you tell him I sent you, he may give you the special discounted rates on food and drink.{br}To find the Lion's Pride Inn, travel south along the road from here -- you can't miss it!",o="Speak with Innkeeper Farley at the Lion's Pride Inn.",r="Rest and relaxation for the tired and cold -- that's our motto! Please, take a seat by the fire and rest your weary bones.{br}Would you like to try a sampling of some of our fine food and drink?"},upd=1792846946,xp=165,y="q",zone=12}
L[#L+1]={cen="A Peon's Burden",choice={{c=5,id=4540},{c=5,id=159}},give={id=6786,k="npc",m=14,n="Ukor",x=0.52,y=0.683},id=2161,lvl=5,mn=1,money=0,pl=6,rc=434,t="Die Bürde eines Peons",turn={id=6928,k="npc",m=14,n="Innkeeper Grosk",x=0.515,y=0.416},tx={d="Excuse me? Can you help me?{br}I have a load of food here. I walked along the road and braved scorpids and spiders and worse! I brought the food to the Valley of Trials because I thought they needed it and I like to help out. But they don't need any food! Now I have to take it back to Razor Hill and I'm afraid of all the beasts along the way...{br}Can you take it for me? I'm just a peon, but you're a hero. You fear nothing!{br}Take it to Innkeeper Grosk at the Razor Hill inn. Thank you!",o="Bring Ukor's Burden to Innkeeper Grosk in Razor Hill."},upd=1793359673,y="q",zone=14}
L[#L+1]={cen="Goretusk Liver Pie",give={id=235,k="npc",m=40,n="Salma Saldean",x=0.564,y=0.306},id=22,lvl=12,mn=9,money=0,obj={{name="Goretusk Liver",req=8,txt="Goretusk Liver: 0/8",ty="item"}},pl=10,rc=589,t="Pastete aus Geiferzahnleber",turn={id=235,k="npc",m=40,n="Salma Saldean",x=0.564,y=0.305},tx={d="The onions are peeled. The garlic is minced. The rosemary is crushed. The crust has been baked. The dill weed is chopped. The gravy is simmering. Now all I need for my famous meat pie are 8 Goretusk Livers!",o="Salma Saldean needs 8 Goretusk livers to make a Goretusk Liver Pie."},upd=1792929254,y="q",zone=40}
L[#L+1]={cen="Seek out SI: 7",cl=8,give={id=917,k="npc",m=12,n="Keryn Sylvius",x=0.438,y=0.659},id=2205,lvl=10,mn=10,money=85,pl=10,rc=589,t="Aufsuchen des SI: 7",turn={id=332,k="npc",m=1519,n="Master Mathias Shaw",x=0.784,y=0.708},tx={d="The badge? Oh, it's nothing, fish - nothing you could handle anyhow. By the looks of you, I'd say Mathias is likely to mistake you for the cheese delivery girl instead of a proper rogue. Regardless, I've been assigned a job and I've made a promise to deliver on that job.{br}Speaking of which, deliver this package to Mathias and he may give you a small task or two.{br}Get cracking.",o="Deliver Keryn Sylvius's package to Master Mathias Shaw at the Stormwind Barracks.",p="Can I help you, Rogue?",r="You found me - and by looking at you, I'd say the run and subsequent search may have been a great strain on your system, both mentally and physically.{br}Would you like Renzik to show you the way to an inn or are you ready for some work?"},upd=1792932375,xp=315,y="q",zone=12}
L[#L+1]={cen="Snatch and Grab",cl=8,fixed={{c=1,id=7298}},give={id=332,k="npc",m=1519,n="Master Mathias Shaw",x=0.784,y=0.708},id=2206,lvl=10,mn=10,money=0,obj={{name="Defias Shipping Schedule",req=1,txt="Defias Shipping Schedule: 0/1",ty="item"}},pi={[2205]=1},pl=11,po=1,pre={2205},rc=589,t="Schneller Eingriff",turn={id=332,k="npc",m=1519,n="Master Mathias Shaw",x=0.783,y=0.707},tx={d="Our operatives in the field are reporting heavy Defias activity south of Goldshire. The reports indicate that the Defias have taken over Jerod's Landing and are now using it as a way to smuggle large quantities of contraband from Redridge to Westfall.{br}I need you to infiltrate the dock house and get me that shipping schedule, $N. You will probably find it buried deep in the pockets of the Dockmaster.{br}...and $N, should you be discovered, SI:7 will disavow all knowledge of your existence.",o="Find the Defias Dockmaster and recover the Shipping Schedule for Master Mathias Shaw."},upd=1792932564,y="q",zone=1519}
L[#L+1]={cen="Simple Parchment",cl=1,give={id=3143,k="npc",m=14,n="Gornek",x=0.421,y=0.683},id=2383,lvl=1,mn=1,money=0,pl=4,pre={788},rc=50,rep={Orgrimmar=50},t="Einfaches Pergament",turn={id=3153,k="npc",m=14,n="Frang",x=0.429,y=0.694},tx={d="Ah, while you were gone a parchment came for you, $N.{br}Read it when you have time. If I'm not mistaken, it came from the warrior trainer Frang. He would have words with you when you're ready. You'll find him outside the Den, taking cover in the shade.",o="Read the Simple Parchment and speak to Frang in the Valley of Trials.",p="What's that you have there? A parchment? You're not a scholar, I hope...",r="Ah, that's my parchment. I heard you'd be coming to the Valley, $N. I'm glad to see you made it--let's hope you survive the trials ahead. Like I said, as you gain in power, come to me--I will do what I can to train you in the ways of the Warrior.{br}Good luck, $N, and return to me whenever you feel ready."},upd=1793313307,xp=50,y="q",zone=14}
L[#L+1]={cen="Call of Fire",cl=64,give={id=3173,k="npc",m=14,n="Swart",x=0.544,y=0.426},id=2983,lvl=10,mn=10,money=0,pl=10,rc=434,t="Ruf des Feuers",turn={id=5907,k="npc",m=17,n="Kranal Fiss",x=0.56,y=0.2},tx={d="It's been some time since you were tested last, $N. You've been patient thus far in your studies, but it's time for you to learn about greater powers... it's time you learn real power. The element of fire is yours if you're prepared to pay for it.{br}Seek out Kranal Fiss in the Barrens. He lives in a small dwelling north of the Crossroads, but be mindful, if you've reached the blasted night elf lands, you've gone way too far.",o="Find Kranal Fiss in the Barrens.",r="Hmmm, Swart sent you to me, did he?{br}Well then, Swart could always be trusted, so that must mean you're ready to take part of the next sapta--the sapta of fire.{br}I see it in your eyes already, the burning, the desire. You've tasted power, and now you're ready for more of it. Patience, $N. Remember what earth taught you. Power and destruction will come easily, but you must still know when to stay your hand."},upd=1793053351,xp=630,y="q",zone=14}
L[#L+1]={cen="Rune-Inscribed Tablet",cl=64,give={id=3143,k="npc",m=14,n="Gornek",x=0.421,y=0.684},id=3084,lvl=1,mn=1,money=0,pl=2,pre={788},rc=128,rep={["Darkspear Trolls"]=50},t="Mit Runen beschriftete Schrifttafel",turn={id=3157,k="npc",m=14,n="Shikrik",x=0.425,y=0.69},tx={d="Ah, while you were gone a tablet came for you, $N.{br}Read it when you have time. If I'm not mistaken, it came from the shaman trainer Shikrik. She would have words with you when you're ready.",o="Speak to Shikrik in the Valley of Trials.",p="Ah, welcome, $N. I'm pleased you have arrived. My days have become long and even busy what with so many students to teach, but the coming of one of your ilk brings me a great sense of accomplishment--I remember the days when I was taught by one of your shamans.",r="As you probably know, the elements give us our power. Fire, earth, water and air--these are our tools.{br}Our strength comes from the spirits of our ancestors. We are the leaders of our people. Like Thrall is to the Horde, so shall we be to the villages and towns we visit. They will look to us for wisdom and protection. To be better prepared, you must train often. When you feel you've gained more power, come to me and I shall teach you what I can."},upd=1793357095,xp=50,y="q",zone=14}
L[#L+1]={cen="Etched Parchment",cl=4,give={id=3143,k="npc",m=14,n="Gornek",x=0.421,y=0.684},id=3087,lvl=1,mn=1,money=0,pl=2,pre={788},rc=50,rep={Orgrimmar=50},t="Geätztes Pergament",turn={id=3154,k="npc",m=14,n="Jen'shan",x=0.428,y=0.692},tx={d="Ah, while you were gone a parchment came for you, $N.{br}Read it when you have time. If I'm not mistaken, it came from the hunter trainer Jen'shan. She would have words with you when you're ready.",o="Read the Etched Parchment and speak to Jen'shan in the Valley of Trials.",p="Ah, so you come at last. Good. Jen'shan be waitin' for you.{br}Many tink it be an easy path, but Jen'shan tell you dat not true. Mastering da beasts of Durotar and beyond take as much skill as masterin' the arcane arts or speakin' to our ancestors.{br}Firin' a bow or rifle may not be as dangerous to you as castin' a spell, but it sure be as dangerous to your enemy.",r="When we finish speakin', you should talk to da rest of da citizens in da Valley. They ask you to do tings for them... tings that will test your skill and teach you some of da dangers of this land.{br}As you grow in experience and wisdom, you be needin' Jen'shan to show you better techniques and skills. Come back to Jen'shan often. I will let you know what I can teach you."},upd=1793307054,xp=50,y="q",zone=14}
L[#L+1]={cen="Rune-Inscribed Parchment",cl=64,give={id=3143,k="npc",m=14,n="Gornek",x=0.421,y=0.684},id=3089,lvl=1,mn=1,money=0,pl=2,pre={788},rc=50,rep={Orgrimmar=50},t="Mit Runen beschriftetes Pergament",turn={id=3157,k="npc",m=14,n="Shikrik",x=0.424,y=0.69},tx={d="Ah, while you were gone a parchment came for you, $N.{br}Read it when you have time. If I'm not mistaken, it came from the shaman trainer Shikrik. She would have words with you when you're ready.",o="Read the Rune-Inscribed Parchment and speak to Shikrik in the Valley of Trials.",p="So, you've arrived. I was beginning to wonder when you would show yourself. I sent the parchment some time ago--I wasn't sure if it had arrived.{br}But enough chatter... you're here because you have been chosen, chosen to lead the spiritual lives of our people.",r="You will be the conduit in which our ancestors communicate. You will have the power of the elements at your beck and call. Sundering your enemies will be child's play; healing your allies as easy as breathing. Keep these things in mind as you face new challenges, and come back to me as often as you'd like. I will remain here to teach you new spells and set you on the correct path when you are ready."},upd=1793353493,xp=50,y="q",zone=14}
L[#L+1]={cen="Encrypted Letter",cl=8,give={id=197,k="npc",m=12,n="Marshal McBride",x=0.489,y=0.416},id=3102,lvl=1,mn=1,money=0,pl=4,pre={7},rc=589,rep={Stormwind=55},t="Verschlüsselter Brief",turn={id=915,k="npc",m=12,n="Jorik Kerridan",x=0.503,y=0.399},tx={d="I was asked to bring this to your attention as soon as you returned from the kobold camps, $N. It appears to be a letter sealed with the insignia of Jorik, one of our local trainers. I wouldn't hesitate to read it before you go about any other business here in the Abbey.",o="Read the Encrypted Letter and speak to Jorik Kerridan in the stable behind Northshire Abbey.",p="You made it here in one piece, and it doesn't look like too many people saw you. Good enough for me. I don't like to have much attention drawn to me back here... nice and quiet. I'm sure you can understand.{br}Have any trouble yet? I'm glad to hear not. That'll change soon enough.",r="You're gonna find that there a number of outfits that'll covet our skills, $N. Adventurers, SI:7... heck, even the Defias Brotherhood wouldn't mind a spy or two inside Stormwind. But you remember this, you're your own man. Don't let nobody bully you into doing something you don't wanna do! Besides, we hold all the cards... at least, we do before the game's done. Know what I mean?{br}Anyway, just wanted to introduce myself and let you know that I'm here if you need any training. Come by anytime."},upd=1792844984,xp=60,y="q",zone=12}
L[#L+1]={cen="Wolves Across the Border",choice={{c=1,id=80},{c=1,id=6070}},give={id=196,k="npc",m=12,n="Eagan Peltskinner",x=0.489,y=0.402},id=33,lvl=2,mn=1,money=0,obj={{item=750,name="Tough Wolf Meat",req=8,txt="Tough Wolf Meat: 0/8",ty="item"}},pl=1,pre={5261},qi={[750]={u299=7,u69=2}},rc=589,rep={Stormwind=110},t="Wölfe an der Grenze",ta={max=1520,min=1520,n=1,sum=1520},tm={max=815,min=815,n=1,sum=815},tr={max=1240,min=1240,n=1,sum=1240},turn={id=196,k="npc",m=12,n="Eagan Peltskinner",x=0.489,y=0.402},tx={d="I hate those nasty timber wolves! But I sure like eating wolf steaks... Bring me tough wolf meat and I will exchange it for something you'll find useful.{br}Tough wolf meat is gathered from hunting the timber wolves and young wolves wandering the Northshire countryside.",o="Bring 8 pieces of Tough Wolf Meat to Eagan Peltskinner outside Northshire Abbey.",p="Hey $N. I'm getting hungry...did you get that tough wolf meat?",r="You've been busy! I can't wait to cook up that wolf meat...{br}I have some things here you might want - take your pick!"},upd=1792844504,xp=255,y="q",zone=12}
L[#L+1]={cen="Mura Runetotem",give={id=3448,k="npc",m=17,n="Tonga Runetotem",x=0.523,y=0.319},id=3301,lvl=15,mn=10,pre={880},rc=434,t="Mura Runentotem",turn={id=8385,k="npc",m=130,n="Mura Runetotem",x=0.429,y=0.42},upd=1793307054,y="q"}
L[#L+1]={cen="Wine Shop Advert",fixed={{c=1,id=2723}},give={id=1432,k="npc",m=1519,n="Renato Gallina",x=0.637,y=0.737},id=332,lvl=2,mn=1,money=0,pl=9,rc=589,rep={Stormwind=82},t="Weinladen-Werbung",turn={id=1431,k="npc",m=1519,n="Suzetta Gallina",x=0.602,y=0.768},tx={d="If you talk to anyone about wine, then you know we Gallinas sell the best wine in Stormwind. And we're not far, still in the Trade District along the city's lovely canals.{br}Here, take this pamphlet. Bring it to my sister Suzetta at our shop for a complimentary bottle of our famous pinot noir. You won't regret it!",o="Go to the Gallina Winery, and bring Suzetta Gallina the Wine Ticket for a free bottle of wine.",p="Greetings and welcome, $N. Have you yet tried one of our fine wines?",r="Ah, so you've seen Renato? Well here you are, sir. A bottle of our special pinot noir. You'll not find its equal in all of Azeroth!"},upd=1792931713,xp=195,y="q",zone=1519}
L[#L+1]={cen="Harlan Needs a Resupply",give={id=1427,k="npc",m=1519,n="Harlan Bagley",x=0.623,y=0.678},id=333,lvl=2,mn=1,money=17,pl=9,rc=589,rep={Stormwind=55},t="Harlan braucht Nachschub",turn={id=1428,k="npc",m=1519,n="Rema Schneider",x=0.58,y=0.674},tx={d="We've been doing a lot of business lately. It seems like everyone is buying armor and sturdy clothes. Almost like they expect a cold, harsh season ahead...{br}But those are future worries. My worry today is that I'm running out of knitted clothing to sell. I need another load from our supplier.{br}If you can take this request to Rema Schneider at the Canal Tailor and Fit Shop, I'd be most grateful.",o="Go to the Canal Tailor Shop and bring Rema Schneider the Cloth Request from Harlan Bagley.",p="You bring word from Mr. Bagley?",r="It says here that Harlan's business is booming. That's good news, but I wonder why people have need of all that armor. I've heard nothing of open war...is there something the nobles aren't telling us?{br}Well, thank you for bringing the request. Here's your payment, and I'll see to it that Harlan gets his supplies."},upd=1792931811,xp=127,y="q",zone=1519}
L[#L+1]={cen="Package for Thurman",give={id=1428,k="npc",m=1519,n="Rema Schneider",x=0.58,y=0.674},id=334,lvl=2,mn=1,money=0,pl=11,rc=589,rep={Stormwind=83},t="Eine Lieferung für Thurman",turn={id=1429,k="npc",m=1519,n="Thurman Schneider",x=0.525,y=0.835},tx={d="My son Thurman is an apprentice at the Larson Clothiers, in the Mage's Quarter. He was in a hurry today and forgot his shears and needles. I know a great Rogue like you must have important tasks at hand, but without his tools Thurman can't do his apprentice work!{br}Please, $N. Can you take my son's sewing kit to him? Larson Clothiers is one of two clothing shops in the Mage's Quarter - it's the one deeper in, near the Mage's Tower.",o="Go to the Larson Clothiers in the Stormwind Mage Quarter, and give Thurman Schneider his Sewing Kit.",p="Are you here to buy clothes?",r="Oh, blast! I thought forgetting my kit would free me from work. Now I guess I'll have to help the Larsons with their sewing...{br}Oh, well. Fun will come later I guess."},upd=1792931889,xp=195,y="q",zone=1519}
L[#L+1]={cen="Further Concerns",give={id=240,k="npc",m=12,n="Marshal Dughan",x=0.421,y=0.659},id=35,lvl=10,mn=7,pre={40},rc=589,t="Weitere Sorgen",turn={id=261,k="npc",m=12,n="Guard Thomas",x=0.74,y=0.722},upd=1793307054,y="q"}
L[#L+1]={cen="Stormpike's Delivery",give={id=1416,k="npc",m=1519,n="Grimand Elmore",x=0.597,y=0.339},id=353,lvl=15,mn=9,money=700,pl=11,pre={1097},rc=589,t="Stormpikes Lieferung",turn={id=1343,k="npc",m=38,n="Mountaineer Stormpike",x=0.248,y=0.184},tx={d="The Stormpikes are a respected dwarven clan, and are well known for their fine and discerning tastes. So it's no wonder that Gringer Stormpike, a Mountaineer of Ironforge, commissioned me to craft him a weapon.{br}The weapon is finished, but... Mountaineer Stormpike is far away, in distant Loch Modan. If you plan on traveling to the north, can you deliver this package to him?{br}My last message from Mountaineer Stormpike said he's stationed at the northern guard tower in Loch Modan.",o="Deliver the Package for Stormpike to Mountaineer Stormpike in Loch Modan."},upd=1792935236,y="q",zone=1519}
L[#L+1]={cen="Westfall Stew",give={id=238,k="npc",m=40,n="Verna Furlbrow",x=0.6,y=0.195},id=36,lvl=10,mn=9,money=0,pl=10,rc=589,rep={Stormwind=55},t="Westfall-Eintopf",turn={id=235,k="npc",m=40,n="Salma Saldean",x=0.564,y=0.306},tx={d="I never thought the day would come when I'd leave the farm. But the fields are overrun with thieves and it's far too dangerous for us here now. As soon as Farmer Furlbrow gets the wagon fixed, we'll be on our way. {br}Maybe you could do me a favor? Let me scribble down my recipe for Westfall stew. Please take it to Salma Saldean over on the farm yonder. The Saldean's farm is just beyond the fork in the road.",o="Verna Furlbrow wants you to deliver her recipe for Westfall Stew to Salma Saldean.",p="I'm going to miss that Verna Furlbrow so much. I don't suppose you happened to see her on your way here?",r="That Verna was always such a sweet lass. We'll miss her here in Westfall but between you and me, she's a city girl at heart and Stormwind will suit her just fine. But enough gossip! Now we can make Westfall Stew!"},upd=1792928995,xp=630,y="q",zone=40}
L[#L+1]={cen="Westfall Stew",fixed={{c=1,id=1479}},give={id=235,k="npc",m=40,n="Salma Saldean",x=0.564,y=0.306},id=38,lvl=13,mn=9,money=0,obj={{name="Stringy Vulture Meat",req=3,txt="Stringy Vulture Meat: 0/3",ty="item"},{name="Murloc Eye",req=3,txt="Murloc Eye: 0/3",ty="item"},{name="Goretusk Snout",req=3,txt="Goretusk Snout: 0/3",ty="item"},{name="Okra",req=3,txt="Okra: 0/3",ty="item"}},pl=10,pre={36},rc=589,t="Westfall-Eintopf",turn={id=235,k="npc",m=40,n="Salma Saldean",x=0.564,y=0.305},tx={d="Help me make some Westfall Stew! Come back with the following ingredients: {br} 3 Stringy Vulture Meat 3 Goretusk Snouts 3 Murloc Eyes 3 Okra",o="Salma Saldean wants 3 Stringy Vulture Meat, 3 Goretusk Snouts, 3 Murloc Eyes, 3 Okra."},upd=1792929254,y="q",zone=40}
L[#L+1]={cen="Milly Osworth",give={id=823,k="npc",m=12,n="Deputy Willem",x=0.482,y=0.43},id=3903,lvl=4,mn=2,money=0,pl=5,pre={18},rc=589,rep={Stormwind=11},t="Milly Geltmark",turn={id=9296,k="npc",m=12,n="Milly Osworth",x=0.506,y=0.393},tx={d="You've shown yourself a dependable rogue, $N. Dependable, and not afraid to get your hands dirty, eh?{br}I have a friend, Milly Osworth, who's in some trouble. She's over with her wagon on the other side of the abbey, near the stable. I'm sure she could use a pair of hands like yours.",o="Speak with Milly Osworth.",r="Oh, Deputy Willem told you to speak with me? He's a brave man and always willing to help, but his duties keep him stuck at Northshire Abbey and I'm afraid the problem I have today is beyond him.{br}Perhaps you can help me?"},upd=1792846007,xp=53,y="q",zone=12}
L[#L+1]={cen="Milly's Harvest",give={id=9296,k="npc",m=12,n="Milly Osworth",x=0.506,y=0.393},id=3904,lvl=4,mn=2,money=0,obj={{item=11119,name="Milly's Harvest",req=8,txt="Milly's Harvest: 0/8",ty="item"}},pl=5,pre={3903},qi={[11119]={u38=2}},rc=589,rep={Stormwind=55},t="Millys Ernte",ta={max=10060,min=5470,n=2,sum=15530},tm={max=2080,min=780,n=2,sum=2860},tr={max=2080,min=780,n=2,sum=2860},turn={id=9296,k="npc",m=12,n="Milly Osworth",x=0.506,y=0.393},tx={d="A gang of brigands, the Defias, moved into the Northshire Vineyards while I was harvesting! I reported it to the Northshire guards and they assured me they'd take care of things, but... I'm afraid for my crop of grapes! If the Defias don't steal them then I fear our guards will trample them when they chase away the thugs.{br}Please, you must help me! I gathered most of my grapes into buckets, but I left them in the vineyards to the southeast.{br}Bring me those crates! Save my harvest!",o="Bring 8 crates of Milly's Harvest to Milly Osworth at Northshire Abbey.",p="Do you have my harvest, $N?",r="Oh thank you, $N! You saved my harvest! And I hope you showed a few of those Defias that they can't cause trouble around here.{br}We might be short on guards these days, but we're lucky to have heroes like you to protect us!"},upd=1792846633,xp=270,y="q",zone=12}
L[#L+1]={cen="Grape Manifest",choice={{c=1,id=11475},{c=1,id=2690}},give={id=9296,k="npc",m=12,n="Milly Osworth",x=0.506,y=0.393},id=3905,lvl=4,mn=2,money=0,pl=6,pre={3904},rc=589,rep={Stormwind=110},t="Traubenliste",turn={id=952,k="npc",m=12,n="Brother Neals",x=0.495,y=0.415},tx={d="Now that my crop is saved, take this Grape Manifest to Brother Neals. He manages the store of food and drink in Northshire, and I'm sure he'll be delighted to hear that he has fresh grapes.{br}You'll find Brother Neals in the abbey, in the bell tower... where he likes to taste his wine.",o="Bring the Grape Manifest to Brother Neals in Northshire Abbey.",p="You look to be in fine spirits! Come! Have a seat, and have a drink!",r="Let's see here...{br}Oh my! Milly's grapes have been saved! When she told me that brigands overran her vineyards I nearly despaired, but my faith in the Light did not waver!{br}And through your bravery, we now have grapes for more wine! May the Light bless you, $N, and keep you safe!"},upd=1792846746,xp=532,y="q",zone=12}
L[#L+1]={cen="Humble Beginnings",give={id=1646,k="npc",m=1519,n="Baros Alexston",x=0.578,y=0.48},id=399,lvl=15,mn=10,money=700,obj={{name="A Simple Compass",req=1,txt="A Simple Compass: 0/1",ty="item"}},pl=11,rc=589,t="Ein bescheidener Anfang",turn={id=1646,k="npc",m=1519,n="Baros Alexston",x=0.577,y=0.479},tx={d="It seems an eternity since I was a boy working the farm in Westfall. They say you can never go back, and it's true. Doubly true in my case, my family's home has been burned down and taken over by thieves.{br}I have spoken with my father about the fate of some of my possessions, including my first compass. He was unable to save them. However, he also says that they should be hidden away on the farm.{br}You'll find the Alexston Farmstead west of Sentinel Hill. Perhaps you could go and retrieve it for me?",o="Go to Baros Alexston's house in Westfall and search for his compass, then return it to him in Cathedral Square of Stormwind."},upd=1792935599,y="q",zone=1519}
L[#L+1]={cen="A Fishy Peril",give={id=241,k="npc",m=12,n="Remy \"Two Times\"",x=0.422,y=0.672},id=40,lvl=10,mn=7,money=0,pl=7,rc=589,rep={Stormwind=11},t="Gefahr aus dem Wasser",turn={id=240,k="npc",m=12,n="Marshal Dughan",x=0.421,y=0.66},tx={d="$N, there's a new threat in Elwynn Forest! Murlocs are swimming up the streams of eastern Elwynn, scaring away fish and attacking gentle folk!{br}I warned Marshal Dughan, but he's more worried about the gnolls and the bandits. He's not convinced that the murlocs are a danger.{br}Please, $N, speak to Dughan and persuade him to send more troops to the east!",o="Remy \"Two Times\" wants you to speak with Marshal Dughan in Goldshire.",r="Yes, I spoke with Remy. I respect him as a merchant, though all reports of Murlocs to the east have been sketchy at best.{br}Your concerns are noted, but unless I receive a military report of a murloc threat, we can't afford to send more troops east."},upd=1792880341,xp=128,y="q",zone=12}
L[#L+1]={cen="Intercepted Shipment",give={id=60502,k="npc",m=33,n="'Slip'",x=0.281,y=0.767},id=40222,lvl=30,mn=25,obj={{name="Refined Gem Shipment",req=1,txt="Refined Gem Shipment: 0/1",ty="item"}},t="Intercepted Shipment",turn={id=60502,k="npc",m=33,n="'Slip'",x=0.281,y=0.767},upd=1793307054,y="q"}
L[#L+1]={cen="Zalazane's Fall",give={id=3188,k="npc",m=14,n="Master Gadrin",x=0.56,y=0.747},id=40389,lvl=10,mn=7,money=175,pl=9,pre={826},rc=434,rep={["Darkspear Trolls"]=250},t="Zalazane's Fall",turn={id=10540,k="npc",m=1637,n="Vol'jin",x=0.344,y=0.364},tx={d="If you don't require assistance from my assistant, could you please do our tribe a favor? Our chieftain, Vol'jin, remains in Grommash Hold, providing counsel to the Warchief as he grapples with several losses he has suffered since leaving the Darkspear Isles.{br}Take Zalazane's head to Vol'jin, assuring him that his people are primed and ready to share in his burdens.",o="Take Zalazane's Head to Vol'jin in Grommash Hold.",p="I do not have long to speak, shaman. What is it you bring to me?",r="The head of Zalazane? No, it could never be that easy.{br}<As you and the great chieftain observe the witchdoctor's head, it slowly loses its form and resembles that of another troll, perhaps a mindslave>.{br}It will not be so easy to reclaim the Echo Isles from Zalazane and his army of slaves, but at least we have contained the threat for now.{br}There are those who will not understand my decision to keep Thrall from reclaiming the isles for my tribe, but we are indebted once to the Warchief and his people and now we will prove that their faith was not misplaced. When the time comes, $N, I ho"},upd=1793055146,xp=1020,y="q",zone=14}
L[#L+1]={cen="The Second Wave",give={id=61026,k="npc",m=14,n="Warbringer Dar'nakk",x=0.527,y=0.416},id=40665,lvl=10,mn=5,money=0,obj={{ids={[60898]=1},name="Expedition Scout",req=7,txt="Expedition Scout slain: 0/7",ty="monster"},{ids={[60893]=2},name="Expedition Commando",req=7,txt="Expedition Commando slain: 0/7",ty="monster"}},pl=5,rc=434,rep={Orgrimmar=150},t="The Second Wave",ta={max=14130,min=14130,n=1,sum=14130},tm={max=2720,min=2720,n=1,sum=2720},tr={max=4440,min=4440,n=1,sum=4440},turn={id=61026,k="npc",m=14,n="Warbringer Dar'nakk",x=0.527,y=0.416},tx={d="War is upon our lands, hunter.{br}The arrogant Kul Tirans think us weak and it is up to the brave sons and daughters of the Horde to teach them otherwise!{br}A second wave of their old fleet, the same we vanquished years ago, has landed just off our shores, posing a threat to our people.{br}On the southern edge of the Echo Isles, their scouts and commandos can be found, probing and plotting for their next move. Slay them in the name of the Horde, and return to me!",o="Slay 7 Expedition Scouts and 7 Expedition Commandos for Warbringer Dar'nakk in Razor Hill in Durotar.",r="You have done well, but do not yet sing for victory: Our foe is as vicious as it is relentless."},upd=1793052743,xp=1350,y="q",zone=14}
L[#L+1]={cen="Expedition Supplies",give={id=61026,k="npc",m=14,n="Warbringer Dar'nakk",x=0.527,y=0.416},id=40666,lvl=12,mn=5,money=0,obj={{item=60911,name="Bundle of Expedition Supply",req=6,txt=": 0/6",ty="item"}},pl=5,qi={[60911]={u60893=1,u60898=1}},rc=434,rep={Orgrimmar=150},t="Expedition Supplies",ta={max=13650,min=13650,n=1,sum=13650},tm={max=945,min=945,n=1,sum=945},tr={max=1890,min=1890,n=1,sum=1890},turn={id=61026,k="npc",m=14,n="Warbringer Dar'nakk",x=0.527,y=0.416},tx={d="Only shortly ago, we learned that not all of Daelin Proudmoore's lieutenants were slain in the War for Durotar. We were expecting their return, but we did not think they'd be so well-armed.{br}All wars are fought on supplies, however, and there is no doubt they are stretched thin so far from their homeland.{br}Search their camps on the southern rims of the Echo Isles and pillage their stocks — they may be forced to leave before ever setting foot near Orgrimmar.",o="Gather 6 Bundles of Expedition Supplies for Warbringer Dar'nakk in Razor Hill in Durotar.",p="Have you taken their provisions, shaman?",r="Proudmoore thought us ill-made mongrels, unthinking and mad with bloodlust.{br}But true warfare requires strategic acuity as much as it requires a sharp edge and strong guts.{br}You have done well, $N. We have defeated the Kul Tirans once, we shall defeat them again."},upd=1793052740,xp=1350,y="q",zone=14}
L[#L+1]={cen="The Warchief's Orders",give={id=61026,k="npc",m=14,n="Warbringer Dar'nakk",x=0.527,y=0.416},id=40667,lvl=10,mn=5,money=0,pl=12,pre={40665},rc=434,rep={Orgrimmar=75},t="The Warchief's Orders",turn={id=4949,k="npc",m=1637,n="Thrall",x=0.319,y=0.378},tx={d="You have made glorious battle upon our enemies, $N.{br}The Horde honors those who bear our banner so proudly. For your might, I bestow upon you this commendation. Wear it well, for your next task will take you to our great Orgrimmar.{br}In the Valley of Wisdom, our Warchief waits for tidings of the ongoing Kul Tiran conflict. Tell him all you have done and all you have learned.",o="Speak with Thrall in Orgrimmar about the Kul Tiran threat.",p="Lok-regar no'gal, orc. I bid you welcome.",r="I see you carry Dar'nakk's commendation. I've never known him to grant such accolades freely.{br}You did well in defending our coasts, and for that the Horde owes you its gratitude."},upd=1793055158,xp=225,y="q",zone=14}
