L[#L+1]={cen="Galgar's Cactus Apple Surprise",fixed={{c=10,id=11584}},give={id=9796,k="npc",m=14,n="Galgar",x=0.427,y=0.673},id=4402,lvl=3,mn=1,money=50,obj={{item=11583,name="Cactus Apple",req=10,txt="Cactus Apple: 0/10",ty="item"}},pl=2,pre={788},qi={[11583]={u3098=4,u3124=6}},rc=434,rep={["Darkspear Trolls"]=200,Orgrimmar=200},t="Galgars Kaktusapfel Surprise",ta={max=12149,min=4290,n=4,sum=32139},tm={max=3515,min=1505,n=4,sum=8734},tr={max=6720,min=1759,n=4,sum=12809},turn={id=9796,k="npc",m=14,n="Galgar",x=0.428,y=0.673},tx={d="It sure gets hot out here in the Valley of Trials.{br}<Galgar wipes his brow.>{br}If only I had some cactus apples, I could make my famous cactus apple surprise! Nothing cools you off faster than a piece of that delicious treat.{br}I'll tell you what, $N. If you bring me 10 cactus apples, I'll make you a few portions of cactus apple surprise to take with you on your adventures. If you're interested, you can find cactus apples growing near the cactus plants around here.",o="Bring Galgar 10 Cactus Apples. You remember him saying that they could be found near cactuses.",p="Have you finished collecting cactus apples?",r="Wonderful, $N! As promised, here is your cactus apple surprise plus a little something extra."},upd=1793357763,xp=475,y="q",zone=14}
L[#L+1]={cen="Your Place In The World",give={id=10176,k="npc",m=14,n="Kaltunk",x=0.433,y=0.686},id=4641,lvl=1,mn=1,money=0,pl=1,rc=434,rep={["Darkspear Trolls"]=50,Orgrimmar=50},t="Euer Platz in der Welt",turn={id=3143,k="npc",m=14,n="Gornek",x=0.421,y=0.684},tx={d="Finally, you are of age, $N... of age to battle in the name of the Horde. To conquer for the glory of the Warchief.{br}Yes...{br}<Kaltunk looks you over.>{br}You will do nicely.{br}No doubt you wish to find a great dragon or demon and strangle it with your bare hands, but perhaps it would be wise to start on something less... dangerous.{br}<Kaltunk laughs.>{br}Report to Gornek, he should be able to assign a task better suited to a young hunter. You will find Gornek in the Den, to the west.",o="Speak with Gornek. You recall Kaltunk marking your map with his location and mentioning that Gornek resided in the Den, a building to the west. {br}",r="Another one of Kaltunk's recruits, hm?{br}A sorry state of affairs we find ourselves in if this is the best the Horde can produce. No matter. By the time we think you're ready to leave the Valley, you'll be a proud Hunter of the Horde."},upd=1793356835,xp=50,y="q",zone=14}
