L[#L+1]={cen="Professor Malkovich",cl=8,give={id=3155,k="npc",m=14,n="Rwag",x=0.413,y=0.68},id=50000,lvl=6,mn=2,money=0,pl=4,rc=434,t="Professor Malkovich",turn={id=50002,k="npc",m=1497,n="Professor Malkovich",x=0.512,y=0.698},tx={d="Professor Malkovich is an old friend of mine. He told me to send him someone interested in anatomy.{br}Find him at the bottom of the Apothecarium in Undercity.",o="Talk to Professor Malkovich at the bottom of the Apothecarium in Undercity."},upd=1793316994,y="q",zone=14}
L[#L+1]={cen="Professor Papucho",cl=8,give={id=915,k="npc",m=12,n="Jorik Kerridan",x=0.503,y=0.399},id=50003,lvl=6,mn=2,money=0,pl=4,pre={3102},rc=589,t="Professor Papucho",turn={id=50004,k="npc",m=1537,n="Professor Papucho",x=0.535,y=0.118},tx={d="Professor Papucho is an old friend of mine. He told me to send him someone interested in anatomy.{br}Find him somewhere inside The Forlorn Cavern in Ironforge.",o="Talk to Professor Papucho somewhere inside The Forlorn Cavern in Ironforge."},upd=1792844984,y="q",zone=12}
