L[#L+1]={cen="Bounty on Garrick Padfoot",choice={{c=1,id=6076},{c=1,id=60},{c=1,id=3070}},give={id=823,k="npc",m=12,n="Deputy Willem",x=0.482,y=0.43},id=6,lvl=5,mn=2,money=0,obj={{item=182,name="Garrick's Head",req=1,txt="Garrick's Head: 0/1",ty="item"}},pl=5,pre={18},qi={[182]={u103=2}},rc=589,rep={Stormwind=83},t="Kopfgeld auf Garrick Padfoot",turn={id=823,k="npc",m=12,n="Deputy Willem",x=0.482,y=0.43},tx={d="Garrick Padfoot - a cutthroat who's plagued our farmers and merchants for weeks - was seen at a shack near the vineyards, which lies east of the Abbey and across the bridge. Bring me the villain's head, and earn his bounty!{br}But be wary, $N. Garrick has gathered a gang of thugs around him. He will not be an easy man to reach.",o="Kill Garrick Padfoot and bring his head to Deputy Willem at Northshire Abbey.",p="Did you find Garrick's shack? Are we finally free of that villain?",r="Hah - you caught him! You've done Elwynn a great service, and earned a nice bounty!"},upd=1792846596,xp=503,y="q",zone=12}
L[#L+1]={cen="Kobold Candles",give={id=253,k="npc",m=12,n="William Pestle",x=0.433,y=0.657},id=60,lvl=7,mn=3,obj={{item=772,name="Large Candle",req=8,txt="Large Candle: 0/8",ty="item"}},qi={[772]={u475=3}},rc=589,t="Koboldkerzen",turn={id=253,k="npc",m=12,n="William Pestle",x=0.433,y=0.657},upd=1793307054,y="q"}
L[#L+1]={cen="Lulu Looks Luscious to Lupines",give={id=50608,k="npc",m=12,n="Lulu",x=0.423,y=0.631},id=60007,lvl=8,mn=6,money=0,obj={{ids={[525]=3},name="Mangy Wolf",req=15,txt="Mangy Wolf slain: 0/15",ty="monster"}},pl=10,pre={60005},rc=589,rep={Stormwind=275},t="Lulu Looks Luscious to Lupines",ta={max=15926,min=15926,n=1,sum=15926},tm={max=14926,min=14926,n=1,sum=14926},tr={max=14926,min=14926,n=1,sum=14926},turn={id=50608,k="npc",m=12,n="Lulu",x=0.424,y=0.632},tx={d="Lulu is staring at the wolves surrounding the farm warily. You think you can hear her poor little heart thudding in dread. The wolves are licking their chops, biding their time until they get a chance to strike.{br}An innocent, adorable thing like her shouldn't look so terrified in her own home. It's up to you to ease Lulu's distress.",o="Slay 15 Mangy Wolves around Elwynn Forest, then return to Lulu in Goldshire.",r="Lulu looks around with a new shimmer in her eyes. She prances around merrily, occasionally lowering her head to chomp at some yummy grass.You pat yourself on the back and bask in the fulfillment that comes with aiding a defenseless creature.{br}Lulu instinctively follows you to your next destination."},upd=1792931327,xp=2163,y="q",zone=12}
L[#L+1]={cen="Lucky Coin",give={id=51302,k="npc",m=12,n="Teresa Palin",x=0.464,y=0.469},id=60050,lvl=5,mn=4,obj={{name="Throw Teresa's Copper Coin into the fountain",req=1,txt="Throw Teresa's Copper Coin into the fountain: 0/1",ty="monster"}},rc=589,t="Lucky Coin",turn={id=1431,k="npc",m=1519,n="Suzetta Gallina",x=0.603,y=0.768},upd=1793307054,y="q"}
