L[#L+1]={cen="Duty to the Light",give={id=927,k="npc",m=12,n="Brother Wilhelm",x=0.411,y=0.66},id=60141,lvl=9,mn=8,obj={{item=51868,name="Rockhide Boar Meat",req=8,txt="Rockhide Boar Meat: 0/8",ty="item"}},qi={[51868]={u524=4}},rc=589,t="Duty to the Light",turn={id=1103,k="npc",m=12,n="Eldrin",x=0.792,y=0.69},upd=1793307054,y="q"}
L[#L+1]={cen="Down in the Ridge",choice={{c=1,id=51875},{c=1,id=51876},{c=1,id=51877}},give={id=197,k="npc",m=12,n="Marshal McBride",x=0.489,y=0.417},id=60145,lvl=5,mn=1,money=0,obj={{name="Snufflesnout",req=1,txt="Snufflesnout slain: 0/1",ty="monster"}},pl=4,pre={15},rc=589,rep={Stormwind=110},t="Down in the Ridge",turn={id=197,k="npc",m=12,n="Marshal McBride",x=0.489,y=0.416},tx={d="Hold, $N. I've one more piece of intel for you if you're heading into the Echo Ridge Mine. One of my scouts spoke of a kobold much larger than the rest hiding deep within the heart of the mine.{br}Its size suggests it may be coordinating the other kobolds, which makes its mere existence a great threat to Northshire. Slay it, and we may very well deal a decisive blow to the kobold infestation.{br}I want you to go down into the Echo Ridge Mine and kill the foul creature. Your efforts will be rewarded appropriately.",o="Kill Snufflesnout, then report back to Marshal McBride in Northshire Abbey.",r="Though your journey has only just begun, you've already proven yourself an invaluable asset to Northshire.{br}Choose your reward. You've earned it."},upd=1792845668,xp=525,y="q",zone=12}
L[#L+1]={cen="Stalking the Felstalkers",choice={{c=1,id=51880},{c=1,id=51881},{c=1,id=51882}},give={id=3145,k="npc",m=14,n="Zureetha Fargaze",x=0.429,y=0.691},id=60147,lvl=4,mn=4,money=0,obj={{name="Felstalker",req=10,txt="Felstalker slain: 0/10",ty="monster"}},pl=4,pre={792},rc=434,rep={["Darkspear Trolls"]=100,Orgrimmar=100},t="Stalking the Felstalkers",ta={max=17970,min=2592,n=3,sum=33567},tm={max=10680,min=1625,n=3,sum=16515},tr={max=10680,min=1860,n=3,sum=16750},turn={id=3145,k="npc",m=14,n="Zureetha Fargaze",x=0.429,y=0.691},tx={d="You've fought the vile familiars outside the coven, but the taint in the valley trails deeper.{br}You must go inside the coven and slay the felstalkers. Return and you'll be rewarded.",o="Kill 10 Felstalkers. Return to Zureetha Fargaze outside the Den.",r="You have struck a blow to their numbers, and returned in one piece.{br}Take one, you earned it."},upd=1793358995,xp=312,y="q",zone=14}
L[#L+1]={cen="Shipment to Stormwind",choice={{c=15,id=1178},{c=5,id=1177},{c=2,id=2454}},give={id=253,k="npc",m=12,n="William Pestle",x=0.433,y=0.657},id=61,lvl=7,mn=3,money=350,pre={60},rc=589,rep={Stormwind=165},t="Lieferung nach Stormwind",turn={id=279,k="npc",m=1519,n="Morgan Pestle",x=0.631,y=0.745},tx={p="Oh, a shipment from my brother? Splendid! Fortune truly shines on me today!",r="Here is your payment ... and while you're here, take a look around! I'm sure we have a potion or other trinket you'd find useful."},upd=1792883420,xp=1185,y="q",zone=1519}
L[#L+1]={cen="A Swift Message",give={id=491,k="npc",m=40,n="Quartermaster Lewis",x=0.57,y=0.472},id=6181,lvl=10,mn=10,money=0,pl=10,rc=589,rep={Stormwind=27},t="Eine eilige Nachricht",turn={id=523,k="npc",m=40,n="Thor",x=0.566,y=0.526},tx={d="Although we don't get much aid from Stormwind directly, I do have a contact in the city who helps supply us with armor. His name is Osric Strang. His shop, Limited Immunity, is in the Old Town of Stormwind.{br}Our supply of armor dwindles, and I must contact Osric for more. Can you take him this note?{br}The fastest way to Stormwind is through Thor, our gryphon master. He's just down the hill; bring him my note, and then take a gryphon to Stormwind.",o="Bring Lewis' Note to Thor the gryphon master.",p="You look like you're in a hurry. Well, then you came to the right place!",r="You have to get this note to Stormwind? That's not a problem, you can take one of my gryphons!"},upd=1792929207,xp=315,y="q",zone=40}
L[#L+1]={cen="The Fargodeep Mine",give={id=240,k="npc",m=12,n="Marshal Dughan",x=0.421,y=0.659},id=62,lvl=7,mn=4,obj={{name="Scout through the Fargodeep Mine",req=1,txt="Scout through the Fargodeep Mine",ty="event"}},rc=589,t="Die Tiefenschachtmine",turn={id=240,k="npc",m=12,n="Marshal Dughan",x=0.421,y=0.659},upd=1793307054,y="q"}
L[#L+1]={cen="Dungar Longdrink",give={id=1323,k="npc",m=1519,n="Osric Strang",x=0.771,y=0.612},id=6261,lvl=10,mn=10,money=0,pl=11,pre={6281},rc=589,t="Dungar Trinkfest",turn={id=352,k="npc",m=1519,n="Dungar Longdrink",x=0.71,y=0.725},tx={d="$N, I gathered into this crate everything Lewis asked for. Can you take it to him?{br}If you've already spoken to Thor in Westfall, then you can take a gryphon back to him. Dungar Longdrink is our gryphon master, over in the trade district.{br}Speak with Dungar, then get this crate to Lewis as fast as you can. We don't want our fighting men and women in Westfall to go without fresh equipment!",o="Bring Osric's Crate to Dungar Longdrink the gryphon master."},upd=1792932496,y="q",zone=1519}
L[#L+1]={cen="Continue to Stormwind",give={id=523,k="npc",m=40,n="Thor",x=0.566,y=0.526},id=6281,lvl=10,mn=10,money=175,pl=10,pre={6181},rc=589,rep={Stormwind=55},t="Weiter nach Stormwind",turn={id=1323,k="npc",m=1519,n="Osric Strang",x=0.771,y=0.612},tx={d="For a small fee, you can take a gryphon to Stormwind, so you can deliver Lewis' note to Osric. You won't get there faster any other way.{br}If that sounds acceptable, then just speak to me again when you're ready for the ride. I'll charge you a little, but trust me; it'll be worth it!",o="Buy a gryphon ride from the gryphon master Thor, then bring Lewis' Note to Osric Strang, in the shop Limited Immunity, in the Old Town of Stormwind.",p="You've been traveling, eh? Have you been anywhere interesting?",r="Ah, a note from Quartermaster Lewis? I'm not surprised he needs more gear. Sentinel Hill is far away, in a land Stormwind has all but forgotten.{br}Well thank you, $N. Here's some money to cover your travel costs."},upd=1792932496,xp=630,y="q",zone=40}
L[#L+1]={cen="Thazz'ril's Pick",give={id=11378,k="npc",m=14,n="Foreman Thazz'ril",x=0.447,y=0.687},id=6394,lvl=4,mn=3,money=150,obj={{item=16332,name="Thazz'ril's Pick",req=1,txt="Thazz'ril's Pick: 0/1",ty="item"}},pl=4,pre={5441},qi={[16332]={u3101=1}},rc=434,rep={["Darkspear Trolls"]=150,Orgrimmar=150},t="Thazz'rils Hacke",turn={id=11378,k="npc",m=14,n="Foreman Thazz'ril",x=0.446,y=0.686},tx={d="$N, you are a dependable orc. Can I count on you for another task?{br}Some time ago I was surveying the cave to the north for minerals, and I left my favorite pick behind. When I later returned to retrieve it I found the cave was filled with vicious beasts! Will you go into the cave, the Burning Blade Coven, and get my pick?{br}I left it in a chamber with waterfalls. My pick has a spell on it so you can see it in the dark, so you won't have to worry about finding it... just what's guarding it!",o="Bring Thazz'ril's Pick to Foreman Thazz'ril.",p="Have you entered the Burning Blade Coven, $N? Did you find my pick?",r="Great, you got it! Thanks a lot, $N. This is my favorite pick! Now if my peons ever finish chopping down these trees, maybe we can find a nice cave to mine!"},upd=1793317281,xp=556,y="q",zone=14}
L[#L+1]={cen="The Forgotten Heirloom",fixed={{c=10,id=4541},{c=10,id=1179}},give={id=237,k="npc",m=40,n="Farmer Furlbrow",x=0.6,y=0.194},id=64,lvl=12,mn=9,money=0,obj={{name="Furlbrow's Pocket Watch",req=1,txt="Furlbrow's Pocket Watch: 0/1",ty="item"}},pl=10,rc=589,t="Das vergessene Erbstück",turn={id=237,k="npc",m=40,n="Farmer Furlbrow",x=0.6,y=0.194},tx={d="It was horrible! Verna woke me when she heard a ruckus in the fields. The fields were full of hooligans. We left in a rush and I forgot to pack my pocket watch. Verna's pa gave me that watch on our wedding day and I feel just sick knowing those thieves have it. I left the pocket watch in the wardrobe at the farmhouse. Look for the field of pumpkins to the West -- you can't miss it. If you bring it back to me, I'd sure be grateful!",o="Farmer Furlbrow wants you to retrieve his pocket watch from the wardrobe in his farmhouse at the pumpkin farm to the West."},upd=1792928948,y="q",zone=40}
L[#L+1]={cen="Kobold Camp Cleanup",give={id=197,k="npc",m=12,n="Marshal McBride",x=0.489,y=0.416},id=7,lvl=2,mn=1,money=25,obj={{ids={[6]=2},name="Kobold Vermin",req=10,txt="Kobold Vermin slain: 0/10",ty="monster"}},pl=1,pre={783},rc=589,rep={Stormwind=110},t="Säuberung im Koboldlager",ta={max=5530,min=5530,n=1,sum=5530},tm={max=3965,min=3965,n=1,sum=3965},tr={max=4390,min=4390,n=1,sum=4390},turn={id=197,k="npc",m=12,n="Marshal McBride",x=0.489,y=0.416},tx={d="Your first task is one of cleansing, $N. A clan of kobolds have infested the woods to the north. Go there and fight the kobold vermin you find. Reduce their numbers so that we may one day drive them from Northshire.",o="Kill 10 Kobold Vermin, then return to Marshal McBride.",r="Well done, citizen. Those kobolds are thieves and cowards, but in large numbers they pose a threat to us. And the humans of Stormwind do not need another threat.{br}For defeating them, you have my gratitude."},upd=1792844945,xp=255,y="q",zone=12}
L[#L+1]={cen="The Jasperlode Mine",give={id=240,k="npc",m=12,n="Marshal Dughan",x=0.421,y=0.66},id=76,lvl=10,mn=4,money=350,obj={{name="Scout through the Jasperlode Mine",req=1,txt="Scout through the Jasperlode Mine",ty="event"}},pl=9,pre={62},rc=589,t="Die Jaspismine",turn={id=240,k="npc",m=12,n="Marshal Dughan",x=0.421,y=0.659},tx={d="Thanks to you we know the Fargodeep Mine is infested with kobolds. Now we need a scout to investigate the more distant Jasperlode Mine.{br}Explore Jasperlode and confirm any kobold presence. To reach the mine, travel east along the road until you reach the Tower of Azora. From the tower, head north and you'll find the mine in the foothills.",o="Explore the Jasperlode Mine, then report back to Marshal Dughan in Goldshire.",p="Hail, $N. What do you have to report? Have you scouted the Jasperlode Mine?"},upd=1792883074,y="q",zone=12}
L[#L+1]={cen="A Threat Within",give={id=823,k="npc",m=12,n="Deputy Willem",x=0.482,y=0.43},id=783,lvl=1,mn=1,money=0,pl=1,rc=589,rep={Stormwind=55},t="Die Bedrohung von innen",turn={id=197,k="npc",m=12,n="Marshal McBride",x=0.489,y=0.416},tx={d="I hope you strapped your belt on tight, young rogue, because there is work to do here in Northshire.{br}And I don't mean farming.{br}The Stormwind guards are hard pressed to keep the peace here, with so many of us in distant lands and so many threats pressing close. And so we're enlisting the aid of anyone willing to defend their home. And their alliance.{br}If you're here to answer the call, then speak with my superior, Marshal McBride. He's inside the abbey behind me.",o="Speak with Marshal McBride.",r="Ah, good. Another volunteer. We're getting a lot of you these days.{br}I hope it's enough.{br}The human lands are threatened from without, and so many of our forces have been marshaled abroad. This, in turn, leaves room for corrupt and lawless groups to thrive within our borders.{br}It is a many-fronted battle we wage, $N. Gird yourself for a long campaign."},upd=1792844305,xp=60,y="q",zone=12}
L[#L+1]={cen="Vanquish the Betrayers",give={id=3139,k="npc",m=14,n="Gar'Thok",x=0.52,y=0.433},id=784,lvl=7,mn=3,money=175,obj={{ids={[3128]=2},name="Kul Tiras Sailor",req=10,txt="Kul Tiras Sailor slain: 0/10",ty="monster"},{ids={[3129]=2},name="Kul Tiras Marine",req=8,txt="Kul Tiras Marine slain: 0/8",ty="monster"},{name="Lieutenant Benedict",req=1,txt="slain: 0/1",ty="monster"}},pl=5,rc=434,rep={["Darkspear Trolls"]=100,Orgrimmar=100},t="Vernichtet die Verräter",ta={max=17790,min=17790,n=1,sum=17790},tm={max=1185,min=1185,n=1,sum=1185},tr={max=3760,min=3760,n=1,sum=3760},turn={id=3139,k="npc",m=14,n="Gar'Thok",x=0.521,y=0.433},tx={d="Led by Admiral Proudmoore, the humans of Kul Tiras encroached on Durotar, violating the Warchief's pact made with Jaina Proudmoore in order to defeat Archimonde years ago.{br}The human aggression was repelled and Tiragarde Keep fell. But recently, the Admiral's reserves, led by Lieutenant Benedict, have retaken the keep and once again pose a threat to our homeland. These humans show no respect for diplomacy.{br}Prove your honor and travel south to Tiragarde Keep to eliminate the human invaders.",o="Kill 10 Kul Tiras Sailors, 8 Kul Tiras Marines and Lieutenant Benedict and return to Gar'Thok in Razor Hill.",r="Word of your bravery travels fast, Shaman. Tales of your victory at Tiragarde Keep will be heralded in Orgrimmar."},upd=1793017271,xp=945,y="q",zone=14}
L[#L+1]={cen="Thwarting Kolkar Aggression",choice={{c=1,id=4933}},give={id=3140,k="npc",m=14,n="Lar Prowltusk",x=0.545,y=0.749},id=786,lvl=8,mn=5,money=0,obj={{name="Attack Plan: Valley of Trials",req=1,txt="Attack Plan: Valley of Trials destroyed: 0/1",ty="object"},{name="Attack Plan: Sen'jin Village",req=1,txt="Attack Plan: Sen'jin Village destroyed: 0/1",ty="object"},{name="Attack Plan: Razor Hill",req=1,txt="Attack Plan: Razor Hill destroyed: 0/1",ty="object"}},pl=6,rc=434,t="Vereitelung der Kolkaraggression",turn={id=3140,k="npc",m=14,n="Lar Prowltusk",x=0.542,y=0.733},tx={d="Lower your voice, hunter. The Kolkar centaurs lie just over the ridge to the west in Kolkar Crag.{br}Last night while they were raiding, I snuck into their village and discovered that the dirty beasts have a three-tiered attack planned on the trolls and orcs of Durotar.{br}We mustn't let their invasion come to fruition. Perhaps you can muster the might needed to infiltrate Kolkar Crag and destroy their attack plans.{br}Last I saw, they had divided them up amongst three of their leaders.",o="Lar Prowltusk outside of Sen'jin Village wants you to destroy the 3 sets of Attack Plans held within Kolkar Crag."},upd=1793359756,y="q",zone=14}
L[#L+1]={cen="Cutting Teeth",choice={{c=1,id=4915},{c=1,id=4914}},give={id=3143,k="npc",m=14,n="Gornek",x=0.421,y=0.684},id=788,lvl=2,mn=1,money=0,obj={{ids={[3098]=2},name="Mottled Boar",req=10,txt="Mottled Boar slain: 0/10",ty="monster"}},pl=1,pre={4641},rc=434,rep={["Darkspear Trolls"]=100,Orgrimmar=100},t="Scharfe Zähne",ta={max=10130,min=1730,n=5,sum=22640},tm={max=3110,min=1280,n=5,sum=8800},tr={max=3110,min=1280,n=5,sum=8800},turn={id=3143,k="npc",m=14,n="Gornek",x=0.421,y=0.684},tx={d="The first order of business will be to put a little strength in your backbone. I could send you out to the Barrens to hunt kodo, but well, in all honesty, you're more useful to us alive than dead.{br}I believe you would find a good match with the mottled boars you'll find to the north of here.",o="Kill 10 Mottled Boars then return to Gornek at the Den.",r="Hmmm, not bad, $N. But don't let it get to your head...you'll fight tougher than boars in your career.{br}Nonetheless, you've proven yourself well, and your next trial will be against a considerably more dangerous opponent, so you'll need some extra protection."},upd=1793357038,xp=213,y="q",zone=14}
L[#L+1]={cen="Sting of the Scorpid",choice={{c=1,id=4919},{c=1,id=4920}},give={id=3143,k="npc",m=14,n="Gornek",x=0.421,y=0.684},id=789,lvl=3,mn=1,money=0,obj={{item=4862,name="Scorpid Worker Tail",req=10,txt="Scorpid Worker Tail: 0/10",ty="item"}},pl=2,pre={788},qi={[4862]={u3124=38,u3281=1}},rc=434,rep={["Darkspear Trolls"]=100,Orgrimmar=100},t="Stich des Skorpiden",ta={max=11840,min=3360,n=4,sum=29190},tm={max=4585,min=2275,n=4,sum=13935},tr={max=7790,min=2610,n=4,sum=18010},turn={id=3143,k="npc",m=14,n="Gornek",x=0.421,y=0.684},tx={d="Powerful warrior and awkward novice alike have fallen to the venomous sting of the scorpid. You will find large numbers of scorpids northwest of here. Bring me ten of their tails as proof of your prowess in battle.{br}The antidote for their sting is actually made from venom extracted from their stingers. We keep large quantities of antidote for scorpid venom on hand to heal young bloods just like you...{br}But I'm sure you won't be needing any of that, will you?",o="Get 10 Scorpid Worker Tails for Gornek in the Den.",p="The carapace of a scorpid isn't so thick that the strength of a determined Hunter will be deterred. Strike strongly and without doubt, and the scorpids should prove easy prey.",r="There is an important lesson that you must take away from fighting scorpids. The smallest or largest of opponents can still send you to your doom. In fierce combat, any number of things can prove your downfall.{br}I have no more to teach you, $N. You have done well, and I will watch your progress with interest."},upd=1793357780,xp=313,y="q",zone=14}
L[#L+1]={cen="Sarkoth",give={id=3287,k="npc",m=14,n="Hana'zua",x=0.406,y=0.626},id=790,lvl=5,mn=1,money=0,obj={{item=4905,name="Sarkoth's Mangled Claw",req=1,txt="Sarkoth's Mangled Claw: 0/1",ty="item"}},pl=3,qi={[4905]={u3281=5}},rc=434,rep={["Darkspear Trolls"]=100,Orgrimmar=100},t="Sarkoth",turn={id=3287,k="npc",m=14,n="Hana'zua",x=0.406,y=0.627},tx={d="Hunter! I thought I would die out here with none to know of it. While I was hunting the scorpids of the Valley, I came across a particularly vicious-looking one. Hurling myself at it, I managed to inflict a massive blow to its claw before it closed around my leg.{br}I wasn't ready for its stinger though, and it sliced down and into my chest, cutting into my flesh and letting my blood.{br}Please, you must kill the scorpid for me! My honor must be upheld! I fought it up on the plateau to the south.",o="Kill Sarkoth and bring his claw back to Hana'zua.",p="Ahhh... my father always said I would never amount to much, and here, lying beneath a tree as life seeps away, I'm afraid it looks like he was right.{br}At least I wish to die knowing that my last enemy in life lays dead.",r="My blow was not enough to kill him, but looking at the damage I inflicted gives me some small measure of pride. That small measure will be all I have to sustain myself if I die, and in that light, the short list of my life's accomplishments fills me with anger."},upd=1793357918,xp=563,y="q",zone=14}
L[#L+1]={cen="Carry Your Weight",fixed={{c=1,id=11845}},give={id=3147,k="npc",m=14,n="Furl Scornbrow",x=0.499,y=0.403},id=791,lvl=7,mn=4,money=0,obj={{item=4870,name="Canvas Scraps",req=8,txt="Canvas Scraps: 0/8",ty="item"}},pl=7,qi={[4870]={u3128=5,u3129=4}},rc=434,rep={["Darkspear Trolls"]=100,Orgrimmar=100},t="Akzeptiert Euer Schicksal",ta={max=21240,min=21240,n=1,sum=21240},tm={max=205,min=205,n=1,sum=205},tr={max=820,min=820,n=1,sum=820},turn={id=3147,k="npc",m=14,n="Furl Scornbrow",x=0.499,y=0.403},tx={d="Age has rendered me useless in battle. Now I make myself useful in other ways.{br}From this vantage point I watch for invaders. As our strength here grows, I find myself blowing the signal horn less and less.{br}To pass the time I fashion goods to help younger, more able warriors defend our homeland.{br}For you, I can fashion you a bag for your belongings. If such an item would be of use to you, bring me some canvas, a material common to the humans and centaurs.",o="Furl Scornbrow in the Razor Hill watchtower wants 8 Canvas Scraps.",p="I fought proudly alongside the Warchief when these lands were pioneered. The scars of battle mark my skin.{br}The honor of the Horde has been upheld with the help of my axe and battlecry during the defeat of Archimonde, when the unholy alliance was made with the humans and elves, wrought from necessity.{br}But my position as watchman and provider has given me a new sense of worth.",r="Most excellent, $N. Any good Shaman will surely find a use for this bag on the battlefield.{br}I salute your vigor and willingness to die in the name of the Horde!"},upd=1793017648,xp=945,y="q",zone=14}
L[#L+1]={cen="Vile Familiars",choice={{c=1,id=4924},{c=1,id=4925},{c=1,id=4923},{c=1,id=5778}},give={id=3145,k="npc",m=14,n="Zureetha Fargaze",x=0.428,y=0.691},id=792,lvl=4,mn=2,money=0,obj={{ids={[3101]=1},name="Vile Familiar",req=12,txt="Vile Familiar slain: 0/12",ty="monster"}},pl=2,rc=434,rep={["Darkspear Trolls"]=150,Orgrimmar=150},t="Üble Familiare",ta={max=5170,min=3150,n=4,sum=16830},tm={max=3370,min=2350,n=4,sum=11740},tr={max=3370,min=2350,n=4,sum=11740},turn={id=3145,k="npc",m=14,n="Zureetha Fargaze",x=0.429,y=0.691},tx={d="I trust the Valley of Trials will teach you much, young hunter.{br}I was sent to the Valley to guide you, but I have discovered a growing taint here...{br}A group that calls itself the Burning Blade has a coven here in the Valley of Trials. They are skulking in a cave to the northeast, and their Vile Familiars have spilled from its mouth to cause havoc.{br}As your first task against the Burning Blade, I bid you, defeat these familiars. Slay many and, if you survive, return to me.",o="Kill 12 Vile Familiars.{br}Return to Zureetha Fargaze outside the Den.",r="You have done well, $N.{br}Although the Vile Familiars were merely pets of the darker powers within the Burning Blade, your success against them foretells greater deeds ahead."},upd=1793358494,xp=556,y="q",zone=14}
L[#L+1]={cen="Burning Blade Medallion",choice={{c=1,id=4921},{c=1,id=4922},{c=1,id=6713}},fixed={{c=1,id=118}},give={id=3145,k="npc",m=14,n="Zureetha Fargaze",x=0.429,y=0.691},id=794,lvl=5,mn=1,money=0,obj={{item=4859,name="Burning Blade Medallion",req=1,txt="Burning Blade Medallion: 0/1",ty="item"}},pl=4,pre={792},qi={[4859]={u3183=4}},rc=434,rep={["Darkspear Trolls"]=200,Orgrimmar=200},t="Medaillon der Burning Blade",turn={id=3145,k="npc",m=14,n="Zureetha Fargaze",x=0.429,y=0.69},tx={d="Through my divinations, I see that an item of power hides deep within the Burning Blade Coven, guarded by beasts and black magic.{br}It is called the Burning Blade Medallion, and your next task is to find it and remove it from the coven.{br}But be wary, for the medallion may be possessed by an agent of the Burning Blade, and if so then the agent's power would be greater than the familiars you have already encountered.{br}Go, $N. You will find the coven in a cave, to the north and west.",o="Bring the Burning Blade Medallion to Zureetha Fargaze, outside The Den.",p="Is your task complete, $N? Do you have the Burning Blade Medallion?",r="You retrieved it! Well done!{br}Your efforts within the Burning Blade Coven are key in rooting out this cult in the Valley of Trials. But I fear they have further aims in our land.{br}We have not seen the end of them."},upd=1793359003,xp=838,y="q",zone=14}
L[#L+1]={cen="Apple a Day",fixed={{c=5,id=80866}},give={id=80460,k="npc",m=1519,n="Applebough",x=0.658,y=0.464},id=80315,lvl=8,mn=8,money=0,obj={{item=2287,name="Healing Balm",req=1,txt="Healing Balm: 0/1",ty="item"}},pl=11,rc=589,rep={["Silvermoon Remnant"]=165},t="Apple a Day",turn={id=80460,k="npc",m=1519,n="Applebough",x=0.658,y=0.462},tx={d="I've only experienced a few blooms in my time, but this season, things are different. At the ends of my leaves, there are usually pink petals sprouting by now, but instead, my branches are barren! I don't think this is normal. Maybe a druid might know what's wrong with me? They're much older and wiser anyhow.",o="Inspect Applebough and help him grow back his fruit. Speak with a nearby druid to find out Applebough's ailment.",p="Please hurry, Human. I don't know how much longer my leaves have before they completely fall away.",r="I can feel the life flowing back into my leaves, Human. That druid really worked some magic with that salve. I wonder what's inside? I'll study it closely until I find out so that other trees like me don't get sick, too!"},upd=1792936082,xp=1624,y="q",zone=1519}
L[#L+1]={cen="Pinch of Salt",give={id=5941,k="npc",m=14,n="Lau'Tiki",x=0.532,y=0.816},id=80384,lvl=6,mn=6,money=0,obj={{item=81181,name="Crab Shell",req=8,txt="Crab Shell: 0/8",ty="item"}},pl=6,qi={[81181]={u3106=5}},rc=434,t="Pinch of Salt",turn={id=5941,k="npc",m=14,n="Lau'Tiki",x=0.532,y=0.816},tx={d="Dese crabs, troublemakers dey are!{br}Cutting my nets with the claws, scaring all the fish away! Every time I chase them dey bury themselves to the sand, Lau'Tiki isn't as nimble as his younger years.{br}About time for some revenge, pesky shell-walkers will get what dey deserve for messin' with Lau'Tiki!{br}Hunt them, bring me their shells and I might let you in a little secret.",o="Lau'Tiki wants you to bring him 8 Crab Shells."},upd=1793307054,y="q",zone=14}
L[#L+1]={cen="Zalazane's Apprentice",give={id=59990,k="other",n="Shabby Letter"},id=80399,lvl=8,mn=6,obj={{name="Zalazane's Mojo",req=1,txt="Zalazane's Mojo: 1/1",ty="item"},{name="Makasgar's Head",req=1,txt="Makasgar's Head: 1/1",ty="item"}},rc=434,t="Zalazane's Apprentice",turn={id=3188,k="npc",m=14,n="Master Gadrin",x=0.559,y=0.747},upd=1793307054,y="q"}
L[#L+1]={cen="Sarkoth",choice={{c=1,id=4916},{c=1,id=4917}},give={id=3287,k="npc",m=14,n="Hana'zua",x=0.406,y=0.627},id=804,lvl=5,mn=1,money=0,pl=4,pre={790},rc=434,rep={["Darkspear Trolls"]=25,Orgrimmar=25},t="Sarkoth",turn={id=3143,k="npc",m=14,n="Gornek",x=0.421,y=0.684},tx={d="Seeing the deed you have done for me steels my heart. I cannot fall so easily! I must endure!{br}But it remains that I cannot make the trek back to the Den unassisted. Please, $N, return to the Den and tell Gornek of my situation. Perhaps he can help me.",o="Bring the news of Hana'zua's plight to Gornek at the Den."},upd=1793358010,xp=138,y="q",zone=14}
L[#L+1]={cen="Report to Sen'jin Village",give={id=3145,k="npc",m=14,n="Zureetha Fargaze",x=0.429,y=0.69},id=805,lvl=5,mn=1,money=0,pl=6,pre={794},rc=434,rep={["Darkspear Trolls"]=50,Orgrimmar=50},t="Bericht erstatten in Sen'jin",turn={id=3188,k="npc",m=14,n="Master Gadrin",x=0.56,y=0.747},tx={d="Your trials against the Burning Blade are finished... here in the Valley. But I want you to report your findings.{br}Go to the troll village of Sen'jin and seek out Master Gadrin. Sen'jin Village is east out of the valley, then right at the fork.{br}Tell Gadrin of the Burning Blade, and that they have reached the Valley of Trials. Discover from him if they have yet reached Sen'jin.{br}Go, $N, and be swift. I fear the evil found in the Burning Blade Coven is but the herald of a larger threat...",o="Speak with Master Gadrin in Sen'jin Village.",r="Hm... your report comes at a bad time. The Burning Blade is not seen here in Sen'jin, but their evil has taken seed off the coast, on the Echo Isles.{br}The orcs are friends of the Darkspear Trolls. Honorable friends. We want to help the orcs, but... we need help too."},upd=1793359734,xp=282,y="q",zone=14}
L[#L+1]={cen="Dark Storms",give={id=3142,k="npc",m=14,n="Orgnil Soulscar",x=0.522,y=0.432},id=806,lvl=12,mn=4,obj={{name="Fizzle's Claw",req=1,txt="Fizzle's Claw: 0/1",ty="item"}},pre={823},rc=434,t="Dunkle Stürme",turn={id=3142,k="npc",m=14,n="Orgnil Soulscar",x=0.522,y=0.432},upd=1793307054,y="q"}
L[#L+1]={cen="Minshina's Skull",give={id=3188,k="npc",m=14,n="Master Gadrin",x=0.56,y=0.747},id=808,lvl=9,mn=4,money=0,obj={{name="Minshina's Skull",req=1,txt=": 0/1",ty="item"}},pl=6,rc=434,t="Minshinas Schädel",turn={id=3188,k="npc",m=14,n="Master Gadrin",x=0.559,y=0.747},tx={d="I hear the voice of my brother, Minshina, calling to me in my dreams.{br}He was taken by Zalazane, the warlock on the Echo Isles to the east. And he is dead.{br}But death is not freedom for my brother. Minshina's spirit was trapped within his own skull by Zalazane's magics. In my dreams I see it with other skulls, in a circle of power on the largest Echo Isle. As long as it remains there my brother's soul is doomed.{br}Please, $N. Find the circle and retrieve Minshina's skull. Bring it to me.{br}Free him!",o="Retrieve Minshina's skull from the circle of power on the Echo Isles.{br}Bring it to Master Gadrin in Sen'jin Village."},upd=1793359732,y="q",zone=14}
L[#L+1]={cen="Work for Food",fixed={{c=10,id=2888}},give={id=3191,k="npc",m=14,n="Cook Torka",x=0.512,y=0.425},id=814,lvl=6,mn=4,money=0,obj={{item=769,name="Chunk of Boar Meat",req=10,txt="Chunk of Boar Meat: 0/10",ty="item"}},pl=5,qi={[769]={u3099=20}},rc=434,rep={["Darkspear Trolls"]=100,Orgrimmar=100},t="Work for Food",ta={max=25980,min=6930,n=2,sum=32910},tm={max=6690,min=5855,n=2,sum=12545},tr={max=13100,min=6690,n=2,sum=19790},turn={id=3191,k="npc",m=14,n="Cook Torka",x=0.511,y=0.425},tx={d="Cook and clean--that's all I do!{br}You want to eat, you get me some more meat! I don't have all day to hunt and prepare food for all these louses. You got to learn to pull your own weight around here if you wanna be treated equal.{br}Get me some Chunks of Boar Meat if you want to make yourself useful... or you don't want to starve to death.",o="Bring 10 Chunks of Boar Meat to Cook Torka in Razor Hill.",p="You want to eat, you get me some more meat!",r="Get me some Chunks of Boar Meat if you want to make yourself useful..."},upd=1793017325,xp=1350,y="q",zone=14}
L[#L+1]={cen="Break a Few Eggs",fixed={{c=5,id=4540},{c=5,id=117}},give={id=3191,k="npc",m=14,n="Cook Torka",x=0.511,y=0.425},id=815,lvl=8,mn=6,money=225,obj={{item=4890,name="Taillasher Egg",req=3,txt=": 0/3",ty="item"}},pl=7,qi={[4890]={u3122=2}},rc=434,rep={["Darkspear Trolls"]=100,Orgrimmar=100},t="Zerbrecht ein paar Eier",ta={max=10350,min=10350,n=1,sum=10350},tm={max=2275,min=2275,n=1,sum=2275},tr={max=3050,min=3050,n=1,sum=3050},turn={id=3191,k="npc",m=14,n="Cook Torka",x=0.511,y=0.425},tx={d="Bah! I almost forgot I need to get breakfast ready.{br}$N, get yourself movin' and get me some taillasher eggs. I'll need at least three of them if I'm going to have enough for tomorrow's meal.{br}The Bloodtalon taillashers can be fierce, and protect their eggs to the death more often than not. They sometimes bury their eggs too deep in the earth to uncover safely, but if you head to the Echo Isles to the southeast of Sen'jin Village, you can usually find them all over those islands.",o="Bring 3 Taillasher Eggs to Cook Torka in Razor Hill.",p="Breakfast, lunch, dinner! Who cares which meal it is? It still has to be cooked by someone--namely me!",r="You might be weak, but at least you're not clumsy, $N.{br}Here, take this and get outta my way. I've got cooking to do."},upd=1793052655,xp=1050,y="q",zone=14}
L[#L+1]={cen="Lost But Not Forgotten",fixed={{c=1,id=4944}},give={id=3193,k="npc",m=14,n="Misha Tor'kren",x=0.431,y=0.303},id=816,lvl=11,mn=8,money=0,obj={{item=4891,name="Kron's Amulet",req=1,txt="Kron's Amulet: 0/1",ty="item"}},pl=13,qi={[4891]={u3110=2}},rc=434,rep={["Darkspear Trolls"]=100,Orgrimmar=100},t="Verloren, aber nicht vergessen",turn={id=3193,k="npc",m=14,n="Misha Tor'kren",x=0.431,y=0.303},tx={d="$N, please, can you help me? My son Kron went hunting days ago, and he still hasn't returned. He went west towards the Barrens to hunt crocolisks along Southfury River. I fear the worst.{br}As strong as he was, his stubborn pride has always drawn him into trouble. I warned him that the crocolisks were powerful and vicious. He grew angry and stormed off.{br}If you can't find him, at least bring me a sign of his fate... even if you have to open up the stomach of every crocolisk along the Southfury's banks.",o="Bring a sign of Kron's fate to Misha Tor'kren at the farmstead northwest of Razor Hill.",p="I pray that Kron will return to me, but I'm almost certain I know his fate already.",r="Oh, my son... my beautiful son.{br}Uncertain of my son's fate, I have tormented myself since he left. Now that I know what's happened, perhaps I can finally begin to mourn.{br}Thank you, $N. Please take this. I was going to give it to Kron as a gift when he returned successful. Now that I know he is dead, I cannot bear to look at it."},upd=1793054868,xp=1320,y="q",zone=14}
L[#L+1]={cen="Practical Prey",give={id=3194,k="npc",m=14,n="Vel'rin Fang",x=0.559,y=0.74},id=817,lvl=8,mn=5,money=225,obj={{name="Durotar Tiger Fur",req=4,txt=": 0/4",ty="item"}},pl=6,rc=434,t="Praktische Beute",turn={id=3194,k="npc",m=14,n="Vel'rin Fang",x=0.56,y=0.739},tx={d="Many of the hides we use come from Durotar tigers, $N. Blankets, armor, tents: there are a great many reasons we hunt the beasts, and many reasons we let them thrive at the same time.{br}The time has come for us to cull the flock, so to speak. Our numbers grow, and our needs are beginning to overwhelm our stocks. I need more hides if I'm to prepare suitable goods for our people.{br}Bring me 4 Durotar tiger furs, and I shall reward you. You can find them on the islands south of here.",o="Bring 4 Durotar Tiger Furs to Vel'rin Fang in Sen'jin Village."},upd=1793359722,y="q",zone=14}
L[#L+1]={cen="A Solvent Spirit",give={id=3304,k="npc",m=14,n="Master Vornal",x=0.559,y=0.745},id=818,lvl=7,mn=5,money=175,obj={{name="Intact Makrura Eye",req=4,txt=": 0/4",ty="item"},{item=4888,name="Crawler Mucus",req=8,txt=": 0/8",ty="item"}},pl=6,qi={[4888]={u3106=5}},rc=434,t="Ein geistvolles Getränk",turn={id=3304,k="npc",m=14,n="Master Vornal",x=0.559,y=0.744},tx={d="Although my eyes fail me, I still can see clearly enough. More often I must rely on my alchemical skills to aid me in magics that once came easily. But I refuse to take on an apprentice--no troll or orc worthy enough has ever come forward.{br}Are you worthy? Yes, of course you are... of course you think you are.{br}I need a few things. Will you get them for me?{br}I need intact makrura eyes, and vials of crawler mucus. You can find them on any makrura or crawler in Durotar. We shall speak again soon.",o="Bring 4 Intact Makrura Eyes and 8 vials of Crawler Mucus to Master Vornal in Sen'jin Village."},upd=1793359727,y="q",zone=14}
L[#L+1]={cen="Chen's Empty Keg",give={id=4926,k="other",n="Chen's Empty Keg"},id=819,lvl=15,mn=11,rc=434,t="Chens leeres Fässchen",turn={id=3292,k="npc",m=17,n="Brewmaster Drohn",x=0.623,y=0.384},upd=1793307054,y="q"}
L[#L+1]={cen="What Do You Rely On?",give={id=3304,k="npc",m=14,n="Master Vornal",x=0.559,y=0.744},id=820,lvl=10,mn=5,obj={{item=2676,name="Shimmerweed",req=8,txt="Shimmerweed: 0/8",ty="item"}},pre={818},qi={[2676]={u3131=4}},rc=434,t="What Do You Rely On?",turn={id=3304,k="npc",m=14,n="Master Vornal",x=0.559,y=0.744},upd=1793307054,y="q"}
L[#L+1]={cen="Report to Orgnil",give={id=3188,k="npc",m=14,n="Master Gadrin",x=0.56,y=0.747},id=823,lvl=7,mn=4,money=0,pl=6,rc=434,t="Bericht an Orgnil",turn={id=3142,k="npc",m=14,n="Orgnil Soulscar",x=0.522,y=0.432},tx={d="We at Sen'jin Village are not without our own troubles, and we thank you for your aid. But the news you bring regarding the Burning Blade could be trouble for everyone.{br}There is an orc stationed at Razor Hill, Orgnil Soulscar, who polices Durotar from evils such as the Burning Blade! Go to Orgnil and tell him of our plight, as well as your news from the Valley of Trials. He will want to know these things.{br}Razor Hill lies to the north.",o="Speak with Orgnil Soulscar in Razor Hill."},upd=1793359731,y="q",zone=14}
L[#L+1]={cen="From The Wreckage....",choice={{c=1,id=4936},{c=1,id=4928},{c=1,id=4935}},give={id=3139,k="npc",m=14,n="Gar'Thok",x=0.521,y=0.433},id=825,lvl=8,mn=3,money=0,obj={{item=4863,name="Gnomish Tools",req=3,txt="Gnomish Tools: 0/3",ty="item"}},pl=10,pre={784},rc=434,rep={["Darkspear Trolls"]=100,Orgrimmar=100},t="Aus den Wrackteilen geborgen...",ta={max=3790,min=3790,n=1,sum=3790},tm={max=280,min=280,n=1,sum=280},tr={max=280,min=280,n=1,sum=280},turn={id=3139,k="npc",m=14,n="Gar'Thok",x=0.521,y=0.433},tx={d="One of my most observant scouts brings back word that the wreckage of Proudmoore's fleet still remains off the coast of Durotar, just east of Tiragarde Keep.{br}It is no secret that the humans, in alliance with those foul little creatures known as gnomes, have an advanced knowledge of mechanics. We must have a complete understanding of all our potential enemies. And our people will benefit from this new knowledge as well.{br}Swim through the wreckage, $N, and retrieve for me the tools of the Alliance.",o="Gar'Thok of Razor Hill wants you to retrieve 3 Gnomish Tools from the wreckage off the coast.",p="Once we learn how the humans operate their strange machinery, we will stand a greater chance of defeating them in future battles.{br}With our new gained knowledge, the Horde only stands to grow in strength.",r="Your recovery mission was a success, Shaman. I will see to it that these tools get to Orgrimmar with the next caravan.{br}Nicely done."},upd=1793052761,xp=1050,y="q",zone=14}
L[#L+1]={cen="Zalazane",give={id=3188,k="npc",m=14,n="Master Gadrin",x=0.56,y=0.747},id=826,lvl=10,mn=4,money=0,obj={{name="Hexed Troll",req=8,txt="slain: 0/8",ty="monster"},{name="Voodoo Troll",req=8,txt="slain: 0/8",ty="monster"},{name="Zalazane's Head",req=1,txt=": 0/1",ty="item"}},pl=6,pre={805},rc=434,t="Zalazane",turn={id=3188,k="npc",m=14,n="Master Gadrin",x=0.559,y=0.747},tx={d="The witchdoctor Zalazane dwells on the Echo Isles to the east. They are the isles we once called home.{br}From there he sends his trolls to the mainland, to hex our people and drag more of them under his sway.{br}He must be stopped.{br}Defeat Zalazane and his minions -- former Darkspear trolls, now lost to us. Bring me his head and I will know his reign of evil is over.",o="Defeat Zalazane.{br}Kill 8 Voodoo Trolls and 8 Hexed Trolls.{br}Bring Zalazane's Head to Gadrin."},upd=1793359729,y="q",zone=14}
L[#L+1]={cen="The Admiral's Orders",give={id=4881,k="other",n="Aged Envelope"},id=830,lvl=7,mn=1,money=0,pl=9,rc=434,rep={["Darkspear Trolls"]=100,Orgrimmar=100},si=4881,t="Die Befehle des Admirals",turn={id=3139,k="npc",m=14,n="Gar'Thok",x=0.521,y=0.433},tx={d="You open the aged and weathered envelope and discover an official looking document. You recognize the seal of Admiral Proudmoore.{br}This looks important. Perhaps Gar'Thok, the commander of Razor Hill, would be interested in having this information.",o="Take Admiral Proudmoore's Orders to Gar'Thok in Razor Hill.",p="There is a look of concern on your face, Shaman. What have you there?",r="This does not bode well at all. You were wise to bring this information to my attention."},upd=1793017268,xp=945,y="q",zone=14}
L[#L+1]={cen="The Admiral's Orders",give={id=3139,k="npc",m=14,n="Gar'Thok",x=0.521,y=0.433},id=831,lvl=7,mn=1,money=175,pl=9,pre={830},rc=434,rep={["Darkspear Trolls"]=100,Orgrimmar=100},t="Die Befehle des Admirals",turn={id=3230,k="npc",m=1637,n="Nazgrel",x=0.324,y=0.357},tx={d="Humans cannot be trusted. We fought alongside them with a weary heart, knowing they would betray us one day.{br}Admiral Proudmoore's death was not enough to stop his legacy of deceit. The human scum had his plans well laid out before he ever met his demise.{br}His reign won't even die with Benedict it seems. Who knows how long it will be before the next waves of Proudmoore's men land upon our shores.{br}We need to get these orders to Nazgrel in Orgrimmar immediately! He can be found in Thrall's chamber.",o="Deliver Admiral Proudmoore's Orders to Nazgrel in Thrall's chamber in Orgrimmar."},upd=1793055150,xp=945,y="q",zone=14}
L[#L+1]={cen="Hallow's End Treats for Jesper!",ev=12,give={id=15310,k="npc",m=1519,n="Jesper",x=0.566,y=0.519},id=8311,lvl=60,mn=10,money=0,obj={{name="Stormwind Nougat",req=1,txt="Stormwind Nougat: 0/1",ty="item"},{name="Gnomeregan Gumdrop",req=1,txt="Gnomeregan Gumdrop: 0/1",ty="item"},{name="Ironforge Mint",req=1,txt="Ironforge Mint: 0/1",ty="item"},{name="Darnassus Marzipan",req=1,txt="Darnassus Marzipan: 0/1",ty="item"}},pl=11,rc=589,t="Schlotternachtssüßigkeiten für Jesper!",turn={id=15310,k="npc",m=1519,n="Jesper",x=0.565,y=0.518},tx={d="I want to go trick-or-treating, but I can't because I'm sick. If you go for me, I'd trade you the candy you get for some I already have! I think you'd like this candy - it makes you turn into things both funny and scary!{br}Each of the innkeepers in the big cities have candy they give for Hallow's End - talk to them and do the tricks they ask for! Also, a little gnome named Talvash in Ironforge is handing out candy as well. When you have all the candy, bring them back to me here!",o="Speak with the innkeepers of Stormwind, Ironforge, and Darnassus, as well as Talvash del Kissel in Ironforge. Perform the tricks they ask of you in exchange for the treats they offer.{br}Return to Jesper at the Stormwind Orphanage with a Darnassus Marzipan, Gnomeregan Gumdrop, Stormwind Nougat, and Ironforge Mint."},upd=1792935899,y="q",zone=1519}
L[#L+1]={cen="Winds in the Desert",give={id=3293,k="npc",m=14,n="Rezlak",x=0.464,y=0.229},id=834,lvl=9,mn=7,money=300,obj={{item=4918,name="Sack of Supplies",req=5,txt="Sack of Supplies: 0/5",ty="item"}},pl=13,qi={[4918]={u3115=3}},rc=434,t="Wind in der Wüste",turn={id=3293,k="npc",m=14,n="Rezlak",x=0.464,y=0.229},tx={d="I'm Rezlak, one of Gazlowe's boys. Boss sent me to help the orcs here in Durotar. Things'd been going good except for the caravans. Can't manage to keep them safe! Makes my job a little harder, you know?{br}The last shipment--they promised it'd get through!--was snatched by the Dustwind harpies of...where was it...Razorwind Canyon?{br}I gotta have those supplies or I'll never get anything done! Follow the big canyon to the south, you'll find the ravine cut right into the west and east sides of the walls.",o="Retrieve 5 Sacks of Supplies and return them to Rezlak near Orgrimmar."},upd=1793307054,y="q",zone=14}
L[#L+1]={cen="Encroachment",give={id=3139,k="npc",m=14,n="Gar'Thok",x=0.52,y=0.433},id=837,lvl=10,mn=6,obj={{name="Razormane Quilboar",req=4,txt="Razormane Quilboar slain: 0/4",ty="monster"},{name="Razormane Scout",req=4,txt="Razormane Scout slain: 0/4",ty="monster"},{name="Razormane Dustrunner",req=4,txt="Razormane Dustrunner slain: 0/4",ty="monster"},{name="Razormane Battleguard",req=4,txt="Razormane Battleguard slain: 0/4",ty="monster"}},rc=434,t="Übergriff",turn={id=3139,k="npc",m=14,n="Gar'Thok",x=0.52,y=0.433},upd=1793307054,y="q"}
L[#L+1]={cen="Back to Billy",give={id=246,k="npc",m=12,n="\"Auntie\" Bernice Stonefield",x=0.345,y=0.842},id=84,lvl=6,mn=5,money=0,pl=10,pre={86},rc=589,t="Zurück zu Billy",turn={id=247,k="npc",m=12,n="Billy Maclure",x=0.431,y=0.857},tx={d="Here you go. And when you give this pie to that Billy, you tell him I hope he chokes on it!",o="Bring the Pork Belly Pie to Billy Maclure at the Maclure Vineyards."},upd=1792928758,y="q",zone=12}
L[#L+1]={cen="Conscript of the Horde",give={id=3336,k="npc",m=14,n="Takrin Pathseeker",x=0.509,y=0.436},id=840,lvl=12,mn=10,money=0,pl=10,rc=434,rep={["Darkspear Trolls"]=50,Orgrimmar=50},t="Freiwilliger der Horde",turn={id=3337,k="npc",m=17,n="Kargal Battlescar",x=0.623,y=0.193},tx={d="Hmm, you look pretty strong.{br}Listen, my good friend Kargal needs some new recruits for Barrens duty. I know you want to do what's right for the Horde. Well, this is your chance.{br}Take this recruitment letter to Kargal and see if he'll sign it.",o="Follow the western road from Razor Hill to the Barrens over a bridge.{br}Stop at the orc outpost across the bridge.{br}Give Kargal Battlescar at the Barrens outpost your recruitment letter.",p="What do you want, pup? If you're not here for recruitment, I don't have time for you.",r="Oh, so Takrin sent you? He's an excellent scout, I'm not sure what I'd do without him.{br}I'll sign your recruitment letter, but what we really need is someone at the Crossroads."},upd=1793022747,xp=682,y="q",zone=14}
L[#L+1]={cen="Crossroads Conscription",give={id=3337,k="npc",m=17,n="Kargal Battlescar",x=0.623,y=0.193},id=842,lvl=12,mn=10,money=0,pl=10,pre={840},rc=434,rep={["Darkspear Trolls"]=100,Orgrimmar=100},t="Crossroads-Wehrpflicht",turn={id=3338,k="npc",m=17,n="Sergra Darkthorn",x=0.522,y=0.31},tx={d="Take this signed recruitment letter to the Crossroads.{br}Sergra Darkthorn, curse her hide, is in charge there. She's a nasty shaman who will talk your head in circles before she lets you do anything useful. Thrall is convinced she's something special, but I'm not so sure.{br}You'll just have to decide for yourself, pup...",o="Follow the western road from Kargal's Far Watch Outpost.{br}At the T intersection, turn left and follow the road south. {br}Find Sergra Darkthorn at the crossing of roads within the Crossroads.",p="Well well well, what do we have here? Has Kargal deemed me worthy of another recruit?",r="Alright, $N. You want to earn your keep with the Horde? Well there's plenty to do here, so listen close and do what you're told.{br} I see that look in your eyes, do not think I will tolerate any insolence. Thrall himself has declared the Hordes females to be on equal footing with you men. Disrespect me in the slightest, and you will know true pain."},upd=1793022920,xp=1365,y="q",zone=17}
L[#L+1]={cen="Lost Necklace",give={id=246,k="npc",m=12,n="\"Auntie\" Bernice Stonefield",x=0.345,y=0.844},id=85,lvl=6,mn=5,money=0,pl=8,rc=589,rep={Stormwind=27},t="Die verlorene Halskette",turn={id=247,k="npc",m=12,n="Billy Maclure",x=0.432,y=0.857},tx={d="I lost my necklace, and think that guttersnipe Billy Maclure took it! He's usually scuttling like a rat around the Maclure vineyards east of here. {br}Get my necklace back for me, and you'll warm an old widow's heart.",o="Speak with Billy Maclure.",r="You lost a what? Well I didn't take no necklace, because I ain't no thief!{br}I might know who did but...<grin>...I'm too hungry to remember."},upd=1792924140,xp=202,y="q",zone=12}
L[#L+1]={cen="Pie for Billy",give={id=247,k="npc",m=12,n="Billy Maclure",x=0.432,y=0.857},id=86,lvl=6,mn=5,money=0,obj={{name="Chunk of Boar Meat",req=4,txt="Chunk of Boar Meat: 4/4",ty="item"}},pl=10,pre={85},rc=589,rep={Stormwind=83},t="Pastete für Billy",turn={id=246,k="npc",m=12,n="\"Auntie\" Bernice Stonefield",x=0.345,y=0.842},tx={d="Maybe if I got a pie, I could tell you who has that necklace. And you know, I think that old Bernice lady at that other farm makes great Pork Belly Pies... {br}Maybe if you gave her some chunks of boar meat from the boars that hang around our farms, and told her what it was for, she'd bake up a pie for you.",o="Bring 4 Chunks of Boar Meat to Auntie Bernice Stonefield at the Stonefield's Farm.",p="I don't think it's right feeding the boy who stole my necklace in the first place, but if that's what it takes to get back what's mine, then so be it!{br}Do you have that boar meat?",r="Though this wild boar meat is tough, simmer it enough and it sure does make for some tasty pie!"},upd=1792928758,xp=608,y="q",zone=12}
L[#L+1]={cen="Princess Must Die!",choice={{c=1,id=1173},{c=1,id=1182},{c=1,id=11191}},give={id=244,k="npc",m=12,n="Ma Stonefield",x=0.347,y=0.845},id=88,lvl=9,mn=6,money=0,obj={{name="Brass Collar",req=1,txt="Brass Collar: 0/1",ty="item"}},pl=8,rc=589,t="Prinzessin muss sterben!",turn={id=244,k="npc",m=12,n="Ma Stonefield",x=0.347,y=0.845},tx={d="The Brackwells have a prize-winning pig, Princess. The sow is HUGE, and she got that way from sneaking over here and eating my veggies!{br}So before she comes to our fields...Princess must die! Bring me her collar as proof of the deed and I'll give you something for your time!{br}Princess is usually over at the Brackwell Pumpkin Patch, to the east and beyond the Maclure farm. Get her before she gets hungry and comes back here!",o="Kill Princess, grab her collar, then bring it back to Ma Stonefield at the Stonefield Farm."},upd=1792881503,y="q",zone=12}
L[#L+1]={cen="The Killing Fields",choice={{c=1,id=3578}},give={id=233,k="npc",m=40,n="Farmer Saldean",x=0.561,y=0.312},id=9,lvl=15,mn=8,money=0,obj={{name="Harvest Watcher",req=20,txt="Harvest Watcher slain: 0/20",ty="monster"}},pl=10,rc=589,t="Tod auf den Feldern",turn={id=233,k="npc",m=40,n="Farmer Saldean",x=0.56,y=0.312},tx={d="Look at what has happened to this place! These lands were once occupied by good farm folk. But the damned thieves have driven them all off. Not me, though! But it seems some Harvest Watchers have taken over the fields.{br}If you're up for the work, I'd like you to go out and kill twenty of them. Come back when you're done for your pay. If you finish up with the ones in my field, clear them from the neighboring fields as well.",o="Farmer Saldean wants you to kill 20 Harvest Watchers."},upd=1792929002,y="q",zone=40}
